// SPDX-License-Identifier: BSD-2-Clause-Patent
// Called by bsd_init in place of its IOKitBSDInit call in the boot candidate.
#include <IOKit/IOLib.h>
#include <pexpert/pexpert.h>
extern "C" {
#include <kern/boot_progress.h>
}
extern "C" int IOKitBSDInit(void);
extern "C" int myron_ufs_register_classes(void);
extern "C" void myron_ufs_probe(void);
#ifndef MYRON_ROOT_BOOT
#define MYRON_ROOT_BOOT 0
#endif
#if MYRON_ROOT_BOOT
extern "C" int myron_start_root(void);
extern "C" int myron_start_data(void);
#endif
extern "C" {
volatile unsigned myron_storage_boot_claimed = 0;
volatile unsigned myron_storage_boot_stage = 0;
volatile int myron_storage_boot_status = kIOReturnNotReady;
}

extern "C" int myron_storage_iokit_bsd_init(void)
{
    // Publish IOBSD and complete the original initialization first. Preserve
    // its return value: an optional diagnostic must not mask a BSD failure.
    boot_progress_stage("IOKitBSDInit enter");
    int result = IOKitBSDInit();
    boot_progress_stage("IOKitBSDInit returned");
    if (result) return result;
    unsigned mode = 0;
    if (!PE_parse_boot_argn("myron27-storage", &mode, sizeof(mode)) ||
        (mode != 1 && mode != 2
#if MYRON_ROOT_BOOT
         && mode != 3
#endif
        )) return result;
    if (!__sync_bool_compare_and_swap(&myron_storage_boot_claimed, 0U, 1U))
        return result;
    myron_storage_boot_stage = 1;
    boot_progress_stage("UFS class registration enter");
    int status = myron_ufs_register_classes();
    myron_storage_boot_status = status;
    IOLog("myron27 storage: registration 0x%x, mode %u\n", status, mode);
    if (status) { myron_storage_boot_stage = 2; return result; }
    myron_storage_boot_stage = 3;
    if (mode >= 2) {
        // The existing bounded transport/GPT probe owns its hardware checks.
        // Root publication additionally needs the separately compiled mode 3.
        myron_storage_boot_stage = 4;
        boot_progress_stage("UFS transport/GPT probe enter");
        myron_ufs_probe();
        boot_progress_stage("UFS transport/GPT probe returned");
        myron_storage_boot_stage = 5;
        IOLog("myron27 storage: transport probe returned; inspect myron_ufs_report\n");
    }
#if MYRON_ROOT_BOOT
    if (mode == 3) {
        // The root entry independently requires both authenticated policies,
        // exact reserve/partition arguments and a valid platform provider.
        myron_storage_boot_stage = 6;
        boot_progress_stage("signed root preparation enter");
        int ready = myron_start_root();
        boot_progress_stage(ready == 1 ? "signed root prepared; publisher queued" : "signed root unavailable");
        myron_storage_boot_status = ready == 1 ? 0 : kIOReturnNotReady;
        myron_storage_boot_stage = ready == 1 ? 8 : 7;
        IOLog("myron27 storage: root preparation %d\n", ready);
        if (ready == 1) {
            boot_progress_stage("volatile Data provider enter");
            int data = myron_start_data();
            boot_progress_stage("volatile Data provider returned");
            IOLog("myron27 storage: volatile Data provider %d; mount requires prepared seed contract\n", data);
        }
    }
#endif
    return result;
}

