UINT64 MyronReadCounter (VOID);
UINT64 MyronReadFrequency (VOID);
EFI_STATUS MyronStockTimeStamp (OUT UINT64 *Value);
VOID MyronPdpSnapshot (UINTN Cluster, UINT32 *State, UINT32 *Magic, UINT16 *Version);

EFI_STATUS MyronCalibrationPrereqProbe (VOID)
{
  UINT64 Frequency, Start, First, Second;
  UINT32 State[2], Magic[2];
  UINT16 Version[2];
  EFI_STATUS Status;
  UINTN Index;
  BOOLEAN Ready;
  Frequency = MyronReadFrequency ();
  if (Frequency < 10 || Frequency > MAX_UINT32) return EFI_UNSUPPORTED;
  Status = MyronStockTimeStamp (&First);
  if (Status != EFI_SUCCESS) return Status;
  Start = MyronReadCounter ();
  while (MyronReadCounter () - Start < Frequency / 10) CpuPause ();
  Status = MyronStockTimeStamp (&Second);
  if (Status != EFI_SUCCESS) return Status;
  DEBUG ((DEBUG_ERROR, MYRON_CAL_TAG ": stock timestamp first=%lx second=%lx\n", First, Second));
  if (Second == First) return EFI_TIMEOUT;
  Start = MyronReadCounter ();
  do {
    Ready = TRUE;
    for (Index = 0; Index < 2; Index++) {
      MyronPdpSnapshot (Index, &State[Index], &Magic[Index], &Version[Index]);
      if (Magic[Index] != 0xABCD9876 || Version[Index] > 2 ||
          ((State[Index] >> 30) != 1 && (State[Index] >> 30) != 2)) Ready = FALSE;
    }
    if (Ready) break;
    CpuPause ();
  } while (MyronReadCounter () - Start < Frequency);
  for (Index = 0; Index < 2; Index++) {
    DEBUG ((DEBUG_ERROR, MYRON_CAL_TAG ": PDP%u state=%x magic=%x version=%u\n",
            Index, State[Index], Magic[Index], Version[Index]));
  }
  return Ready ? EFI_SUCCESS : EFI_NOT_READY;
}
