EFI_STATUS MyronStockTimeStampInterface (OUT UINT64 *Address)
{
  EFI_STATUS Status;
  UINT64 *Kernel = NULL;
  UINT64 *Thread;
  VOID *Hob;
  UINT64 Scheduler;
  STATIC_ASSERT (sizeof (UINTN) == 8, "MYRON stock ABI is AArch64");
