  VOID *Buffer = NULL;
  UINTN Size = 0;
  EFI_HANDLE Child = NULL;
  EFI_STATUS Status;
  EFI_LOADED_IMAGE_PROTOCOL *Loaded;

  Status = GetSectionFromAnyFv(&mLoaderGuid, EFI_SECTION_PE32, 0, &Buffer, &Size);
  if (EFI_ERROR(Status)) return Status;
  if (Buffer == NULL || Size == 0) {
    if (Buffer != NULL) FreePool(Buffer);
    return EFI_LOAD_ERROR;
  }
  /* UEFI's PE loader performs relocation and image authentication. The source
   * buffer may be freed after LoadImage; no fixed FD or payload address here. */
  Status = gBS->LoadImage(FALSE, gImageHandle, NULL, Buffer, Size, &Child);
  FreePool(Buffer);
  if (EFI_ERROR(Status)) return Status;
  Status = gBS->HandleProtocol(Child, &gEfiLoadedImageProtocolGuid, (VOID **)&Loaded);
  if (EFI_ERROR(Status)) {
    gBS->UnloadImage(Child);
    return Status;
  }
  Loaded->LoadOptions = mFirmwareMarker;
  Loaded->LoadOptionsSize = sizeof(mFirmwareMarker);
  Status = gBS->StartImage(Child, NULL, NULL);
  /* A returning UEFI application is unloaded by StartImage itself. */
  return Status;
