STATIC BOOLEAN StringIs (CONST VOID *P, INT32 N, CONST CHAR8 *Text)
{
  UINTN Size = AsciiStrLen (Text) + 1;
  return P != NULL && N == (INT32)Size && CompareMem (P, Text, Size) == 0;
}

STATIC BOOLEAN Compatible (CONST VOID *P, INT32 N)
{
  CONST CHAR8 *S = P;
  INT32 I = 0;
  BOOLEAN Found = FALSE;
  if (P == NULL || N <= 0) return FALSE;
  while (I < N) {
    INT32 End = I;
    while (End < N && S[End] != 0) End++;
    if (End == N) return FALSE;
    if (StringIs (S + I, End - I + 1, "simple-framebuffer")) Found = TRUE;
    I = End + 1;
  }
  return Found;
}

