{
  UINT64 V = Fdt32ToCpu (ReadUnaligned32 ((CONST UINT32 *)P));
  if (Count == 2) V = (V << 32) | Fdt32ToCpu (ReadUnaligned32 ((CONST UINT32 *)(P + 4)));
  return V;
}

EFI_STATUS MyronParseFramebuffer (CONST VOID *Fdt, MYRON_FRAMEBUFFER *Out)
{
  INT32 Node = -1, Depth = 0, N, Parent, Ac, Sc, Chosen;
  CONST VOID *P;
  MYRON_FRAMEBUFFER Candidate;
  BOOLEAN Found = FALSE;
  if (Out == NULL) return EFI_INVALID_PARAMETER;
  ZeroMem (Out, sizeof (*Out));
  if (Fdt == NULL || FdtCheckHeader (Fdt) != 0) return EFI_COMPROMISED_DATA;
  Chosen = FdtPathOffset (Fdt, "/chosen");
  while ((Node = FdtNextNode (Fdt, Node, &Depth)) >= 0 && Depth >= 0) {
    P = FdtGetProp (Fdt, Node, "compatible", &N);
    if (!Compatible (P, N)) continue;
    P = FdtGetProp (Fdt, Node, "status", &N);
    if (StringIs (P, N, "disabled")) continue;
    if (P != NULL && !StringIs (P, N, "okay") && !StringIs (P, N, "ok")) return EFI_UNSUPPORTED;
    if (P == NULL && N != -FDT_ERR_NOTFOUND) return EFI_COMPROMISED_DATA;
    if (Found) return EFI_COMPROMISED_DATA;
    Parent = FdtParentOffset (Fdt, Node);
    // Only direct root/chosen nodes: no unimplemented bus address translation.
    if (Parent != 0 && (Chosen < 0 || Parent != Chosen)) return EFI_UNSUPPORTED;
    P = FdtGetProp (Fdt, Parent, "ranges", &N);
    if ((P != NULL && N != 0) || (P == NULL && N != -FDT_ERR_NOTFOUND)) return EFI_UNSUPPORTED;
    Ac = FdtAddressCells (Fdt, Parent);
    Sc = FdtSizeCells (Fdt, Parent);
    if ((Ac != 1 && Ac != 2) || (Sc != 1 && Sc != 2)) return EFI_UNSUPPORTED;
    P = FdtGetProp (Fdt, Node, "reg", &N);
    if (P == NULL || N != (Ac + Sc) * 4) return EFI_COMPROMISED_DATA;
    ZeroMem (&Candidate, sizeof (Candidate));
    Candidate.Base = Cells (P, Ac);
    Candidate.Bytes = Cells ((CONST UINT8 *)P + Ac * 4, Sc);
    if ((Candidate.Base & 3) || Candidate.Base < DISPLAY_BASE ||
        Candidate.Bytes == 0 || Candidate.Bytes > DISPLAY_BYTES ||
        Candidate.Base - DISPLAY_BASE > DISPLAY_BYTES - Candidate.Bytes) return EFI_UNSUPPORTED;
    if (!U32Prop (Fdt, Node, "width", &Candidate.Width) ||
        !U32Prop (Fdt, Node, "height", &Candidate.Height) ||
        !U32Prop (Fdt, Node, "stride", &Candidate.Stride)) return EFI_COMPROMISED_DATA;
    if (Candidate.Width == 0 || Candidate.Width > 8192 || Candidate.Height == 0 || Candidate.Height > 8192 ||
        (Candidate.Stride & 3) || Candidate.Stride < Candidate.Width * 4 ||
        (UINT64)Candidate.Stride * Candidate.Height > Candidate.Bytes) return EFI_UNSUPPORTED;
    P = FdtGetProp (Fdt, Node, "format", &N);
    if (StringIs (P, N, "a8r8g8b8") || StringIs (P, N, "x8r8g8b8")) {
      Candidate.Format = PixelBlueGreenRedReserved8BitPerColor;
    } else if (StringIs (P, N, "a8b8g8r8") || StringIs (P, N, "x8b8g8r8")) {
      Candidate.Format = PixelRedGreenBlueReserved8BitPerColor;
    } else {
      return EFI_UNSUPPORTED;
    }
    // Report only the scanout extent, not all reserved memory.
    Candidate.Bytes = (UINT64)Candidate.Stride * Candidate.Height;
    *Out = Candidate;
    Found = TRUE;
  }
  if (Node < 0 && Node != -FDT_ERR_NOTFOUND) return EFI_COMPROMISED_DATA;
  return Found ? EFI_SUCCESS : EFI_NOT_FOUND;
}
