STATIC EFI_GUID mEntryArg = {0xdaee82e6,0x8090,0x4e72,{0xbf,0xb9,0x78,0xc1,0x3c,0xd4,0xe3,0x59}};
STATIC EFI_GRAPHICS_OUTPUT_MODE_INFORMATION mInfo;
STATIC EFI_GRAPHICS_OUTPUT_PROTOCOL_MODE mMode;
STATIC FRAME_BUFFER_CONFIGURE *mConfig;

STATIC EFI_STATUS EFIAPI Query (EFI_GRAPHICS_OUTPUT_PROTOCOL *This, UINT32 Number,
                               UINTN *Size, EFI_GRAPHICS_OUTPUT_MODE_INFORMATION **Info)
{
  if (This == NULL || Size == NULL || Info == NULL || Number != 0) return EFI_INVALID_PARAMETER;
  *Info = AllocateCopyPool (sizeof (mInfo), &mInfo);
  if (*Info == NULL) return EFI_OUT_OF_RESOURCES;
  *Size = sizeof (mInfo);
  return EFI_SUCCESS;
}

STATIC EFI_STATUS EFIAPI Set (EFI_GRAPHICS_OUTPUT_PROTOCOL *This, UINT32 Number)
{
  EFI_GRAPHICS_OUTPUT_BLT_PIXEL Black = {0,0,0,0};
  if (This == NULL || Number != 0) return EFI_UNSUPPORTED;
  // No panel registers, clocks or vendor protocol calls. GOP SetMode clears
  // the visible pixels via the same bounded BLT path used by the console.
  return This->Blt (This, &Black, EfiBltVideoFill, 0, 0, 0, 0,
                    mInfo.HorizontalResolution, mInfo.VerticalResolution, 0);
}

STATIC EFI_STATUS EFIAPI Blt (EFI_GRAPHICS_OUTPUT_PROTOCOL *This, EFI_GRAPHICS_OUTPUT_BLT_PIXEL *Buffer,
                             EFI_GRAPHICS_OUTPUT_BLT_OPERATION Op, UINTN Sx, UINTN Sy, UINTN Dx, UINTN Dy,
                             UINTN W, UINTN H, UINTN Delta)
{
  EFI_STATUS Status;
  EFI_TPL Tpl;
  if (This == NULL || Op >= EfiGraphicsOutputBltOperationMax) return EFI_INVALID_PARAMETER;
  Tpl = gBS->RaiseTPL (TPL_NOTIFY);
  Status = FrameBufferBlt (mConfig, Buffer, Op, Sx, Sy, Dx, Dy, W, H, Delta);
  if (!EFI_ERROR (Status) && Op != EfiBltVideoToBltBuffer) {
    WriteBackInvalidateDataCacheRange ((VOID *)(UINTN)mMode.FrameBufferBase, mMode.FrameBufferSize);
  }
  gBS->RestoreTPL (Tpl);
  return Status;
}

STATIC EFI_GRAPHICS_OUTPUT_PROTOCOL mGop = {Query, Set, Blt, &mMode};

EFI_STATUS EFIAPI MyronFdtGopEntry (EFI_HANDLE ImageHandle, EFI_SYSTEM_TABLE *SystemTable)
{
  VOID *Hob;
  UINT64 Address;
  UINTN ConfigSize = 0;
  MYRON_FRAMEBUFFER Fb;
  EFI_STATUS Status;
  EFI_HANDLE Handle = NULL;
  EFI_GUID DisplayGuid = MYRON_DISPLAY_GUID;
  MYRON_DISPLAY_HANDOFF Captured;
  Status = EFI_NOT_FOUND;
  ZeroMem (&Fb, sizeof (Fb));
  Hob = GetFirstGuidHob (&DisplayGuid);
  if (Hob != NULL && GET_GUID_HOB_DATA_SIZE (Hob) == sizeof (Captured)) {
    CopyMem (&Captured, GET_GUID_HOB_DATA (Hob), sizeof (Captured));
    DEBUG ((DEBUG_ERROR, "MYRON36: display HOB status=%u recognized=%u\n", Captured.Status, Captured.Recognized));
    if (Captured.Magic == MYRON_DISPLAY_MAGIC && Captured.Version == 1 && Captured.Status == 1 &&
        Captured.Width != 0 && Captured.Width <= 8192 && Captured.Height != 0 && Captured.Height <= 8192 &&
        Captured.Stride == Captured.Width * 4 && Captured.Format == 1 &&
        Captured.Bytes == (UINT64)Captured.Stride * Captured.Height &&
        Captured.Bytes <= 0x2B00000 && Captured.Base >= 0xFC800000ULL && (Captured.Base & 3) == 0 &&
        Captured.Base - 0xFC800000ULL <= 0x2B00000 - Captured.Bytes) {
      Fb.Base = Captured.Base; Fb.Bytes = Captured.Bytes;
      Fb.Width = Captured.Width; Fb.Height = Captured.Height;
      Fb.Stride = Captured.Stride; Fb.Format = PixelBlueGreenRedReserved8BitPerColor;
      Status = EFI_SUCCESS;
    }
  }
  if (EFI_ERROR (Status)) {
    Hob = GetFirstGuidHob (&mEntryArg);
    if (Hob != NULL && GET_GUID_HOB_DATA_SIZE (Hob) == sizeof (Address)) {
      CopyMem (&Address, GET_GUID_HOB_DATA (Hob), sizeof (Address));
      if (Address != 0 && !(Address & 7))
        Status = MyronParseFramebuffer ((CONST VOID *)(UINTN)Address, &Fb);
    }
  }
  if (EFI_ERROR (Status)) {
    DEBUG ((DEBUG_ERROR, "MYRON36: no usable captured/FDT framebuffer (%r); no display memory written\n", Status));
    return Status;
  }
  mInfo.HorizontalResolution = Fb.Width;
  mInfo.VerticalResolution = Fb.Height;
  mInfo.PixelsPerScanLine = Fb.Stride / 4;
  mInfo.PixelFormat = Fb.Format;
  mMode.MaxMode = 1;
  mMode.Info = &mInfo;
  mMode.SizeOfInfo = sizeof (mInfo);
  mMode.FrameBufferBase = Fb.Base;
  mMode.FrameBufferSize = (UINTN)Fb.Bytes;
  Status = FrameBufferBltConfigure ((VOID *)(UINTN)Fb.Base, &mInfo, NULL, &ConfigSize);
  if (Status != EFI_BUFFER_TOO_SMALL || ConfigSize == 0) return EFI_DEVICE_ERROR;
  mConfig = AllocatePool (ConfigSize);
  if (mConfig == NULL) return EFI_OUT_OF_RESOURCES;
  Status = FrameBufferBltConfigure ((VOID *)(UINTN)Fb.Base, &mInfo, mConfig, &ConfigSize);
  if (!EFI_ERROR (Status)) {
    Status = gBS->InstallMultipleProtocolInterfaces (&Handle,
                &gEfiDevicePathProtocolGuid, &DisplayDevicePath, &gEfiGraphicsOutputProtocolGuid, &mGop, NULL);
  }
  if (EFI_ERROR (Status)) {
    FreePool (mConfig);
    mConfig = NULL;
    return Status;
  }
  DEBUG ((DEBUG_ERROR, "MYRON_MINIMAL: GOP base=%lx %ux%u stride=%u format=%u\n",
          Fb.Base, Fb.Width, Fb.Height, Fb.Stride, (UINT32)Fb.Format));
  if (Fb.Height >= 160) {
    EFI_GRAPHICS_OUTPUT_BLT_PIXEL Yellow = {0,255,255,0};
    mGop.Blt (&mGop, &Yellow, EfiBltVideoFill, 0, 0, 0, 144, Fb.Width, 16, 0);
  }
  return EFI_SUCCESS;
}
