ASM_FUNC(ArmGicV5EnableInterruptInterface)
        mov     x1, #1
        msr     ICC_CR0_EL1, x1
        mov     x1, #0
        msr     ICC_PCR_EL1, x1

        mov     x1, #0
        str     x1, [x0, #IRS_CR0]
        isb

        str     x1, [x0, #IRS_IST_BASER]
        isb

        mov     x1, #1
        str     x1, [x0, #IRS_CR0]
        isb

        ret

