#include "KeyPolicy.h"

BOOLEAN
MyronKeyConfigValid (UINT32 Control)
{
  /* Canoe TLMM: GPIO mux bits 5:2, output enable bit 9. Read only. */
  return Control != MAX_UINT32 && (Control & (0x3CU | 0x200U)) == 0;
}

UINTN
MyronKeySample (MYRON_KEY_STATE *State, BOOLEAN Pressed, UINT64 NowMs)
{
  UINTN Key = MYRON_KEY_NONE;
  if (!State->Initialized) {
    State->Initialized = TRUE;
    State->Raw = State->Stable = Pressed;
    State->RawSince = NowMs;
    return Key;
  }
  if (State->Raw != Pressed) {
    State->Raw = Pressed;
    State->RawSince = NowMs;
    return Key;
  }
  if (NowMs - State->RawSince < MYRON_KEY_DEBOUNCE_MS) return Key;
  if (State->Stable != Pressed) {
    State->Stable = Pressed;
    if (Pressed) {
      State->Tracking = State->Armed;
      State->PressSince = State->RawSince;
    } else {
      if (State->Tracking) {
        Key = State->RawSince - State->PressSince >= MYRON_KEY_HOLD_MS ?
                MYRON_KEY_ENTER : MYRON_KEY_NEXT;
      }
      State->Tracking = FALSE;
    }
  }
  /* Boot-held keys are ignored until a stable release. No autorepeat. */
  if (!Pressed) State->Armed = TRUE;
  return Key;
}
