#define QUEUE_SIZE 8
#define NOTIFY_SIZE 8
typedef struct {
  EFI_KEY_DATA Key;
  EFI_KEY_NOTIFY_FUNCTION Function;
} KEY_NOTIFY;

STATIC EFI_SIMPLE_TEXT_INPUT_PROTOCOL mInput;
STATIC EFI_SIMPLE_TEXT_INPUT_EX_PROTOCOL mInputEx;
STATIC EFI_EVENT mPoll, mExit;
STATIC EFI_HANDLE mHandle;
STATIC MYRON_KEY_STATE mState;
STATIC EFI_KEY_DATA mQueue[QUEUE_SIZE];
STATIC KEY_NOTIFY mNotify[NOTIFY_SIZE];
STATIC UINTN mHead, mCount;
STATIC BOOLEAN mStopped;

STATIC EFI_STATUS EFIAPI
Reset (EFI_SIMPLE_TEXT_INPUT_PROTOCOL *This, BOOLEAN ExtendedVerification)
{
  EFI_TPL Old = gBS->RaiseTPL (TPL_NOTIFY);
  mHead = mCount = 0;
  ZeroMem (&mState, sizeof (mState));
  gBS->RestoreTPL (Old);
  return mStopped ? EFI_DEVICE_ERROR : EFI_SUCCESS;
}

STATIC EFI_STATUS EFIAPI
ReadEx (EFI_SIMPLE_TEXT_INPUT_EX_PROTOCOL *This, EFI_KEY_DATA *Key)
{
  EFI_TPL Old;
  EFI_STATUS Status = EFI_NOT_READY;
  if (Key == NULL) return EFI_INVALID_PARAMETER;
  Old = gBS->RaiseTPL (TPL_NOTIFY);
  if (mCount != 0) {
    *Key = mQueue[mHead];
    mHead = (mHead + 1) % QUEUE_SIZE;
    mCount--;
    Status = EFI_SUCCESS;
  } else if (mStopped) {
    Status = EFI_DEVICE_ERROR;
  }
  gBS->RestoreTPL (Old);
  return Status;
}

STATIC EFI_STATUS EFIAPI
Read (EFI_SIMPLE_TEXT_INPUT_PROTOCOL *This, EFI_INPUT_KEY *Key)
{
  EFI_KEY_DATA Data;
  EFI_STATUS Status;
  if (Key == NULL) return EFI_INVALID_PARAMETER;
  Status = ReadEx (&mInputEx, &Data);
  if (!EFI_ERROR (Status)) *Key = Data.Key;
  return Status;
}

STATIC EFI_STATUS EFIAPI
ResetEx (EFI_SIMPLE_TEXT_INPUT_EX_PROTOCOL *This, BOOLEAN ExtendedVerification)
{
  return Reset (&mInput, ExtendedVerification);
}

STATIC EFI_STATUS EFIAPI
SetState (EFI_SIMPLE_TEXT_INPUT_EX_PROTOCOL *This, EFI_KEY_TOGGLE_STATE *State)
{
  if (State == NULL) return EFI_INVALID_PARAMETER;
  return *State == EFI_TOGGLE_STATE_VALID ? EFI_SUCCESS : EFI_UNSUPPORTED;
}

STATIC BOOLEAN
Matches (EFI_KEY_DATA *Pattern, EFI_KEY_DATA *Key)
{
  return Pattern->Key.ScanCode == Key->Key.ScanCode &&
         Pattern->Key.UnicodeChar == Key->Key.UnicodeChar &&
         (Pattern->KeyState.KeyShiftState == 0 || Pattern->KeyState.KeyShiftState == Key->KeyState.KeyShiftState) &&
         (Pattern->KeyState.KeyToggleState == 0 || Pattern->KeyState.KeyToggleState == Key->KeyState.KeyToggleState);
}

STATIC EFI_STATUS EFIAPI
RegisterNotify (EFI_SIMPLE_TEXT_INPUT_EX_PROTOCOL *This, EFI_KEY_DATA *Key,
                EFI_KEY_NOTIFY_FUNCTION Function, VOID **Handle)
{
  EFI_TPL Old;
  UINTN Index, Free = NOTIFY_SIZE;
  if (Key == NULL || Function == NULL || Handle == NULL) return EFI_INVALID_PARAMETER;
  Old = gBS->RaiseTPL (TPL_NOTIFY);
  for (Index = 0; Index < NOTIFY_SIZE; Index++) {
    if (mNotify[Index].Function == NULL) { Free = Index; continue; }
    if (mNotify[Index].Function == Function &&
        mNotify[Index].Key.Key.ScanCode == Key->Key.ScanCode &&
        mNotify[Index].Key.Key.UnicodeChar == Key->Key.UnicodeChar &&
        mNotify[Index].Key.KeyState.KeyShiftState == Key->KeyState.KeyShiftState &&
        mNotify[Index].Key.KeyState.KeyToggleState == Key->KeyState.KeyToggleState) {
      *Handle = &mNotify[Index];
      gBS->RestoreTPL (Old);
      return EFI_SUCCESS;
    }
  }
  if (Free != NOTIFY_SIZE) {
    mNotify[Free].Key = *Key;
    mNotify[Free].Function = Function;
    *Handle = &mNotify[Free];
  }
  gBS->RestoreTPL (Old);
  return Free == NOTIFY_SIZE ? EFI_OUT_OF_RESOURCES : EFI_SUCCESS;
}

STATIC EFI_STATUS EFIAPI
UnregisterNotify (EFI_SIMPLE_TEXT_INPUT_EX_PROTOCOL *This, VOID *Handle)
{
  EFI_TPL Old;
  UINTN Index;
  Old = gBS->RaiseTPL (TPL_NOTIFY);
  for (Index = 0; Index < NOTIFY_SIZE; Index++) {
    if (Handle == &mNotify[Index] && mNotify[Index].Function != NULL) {
      ZeroMem (&mNotify[Index], sizeof (mNotify[Index]));
      gBS->RestoreTPL (Old);
      return EFI_SUCCESS;
    }
  }
  gBS->RestoreTPL (Old);
  return EFI_INVALID_PARAMETER;
}

STATIC VOID EFIAPI
WaitKey (EFI_EVENT Event, VOID *Context)
{
  if (mCount != 0) gBS->SignalEvent (Event);
}

STATIC VOID EFIAPI
Poll (EFI_EVENT Event, VOID *Context)
{
  EFI_TPL Old;
  EFI_KEY_DATA Key;
  EFI_KEY_NOTIFY_FUNCTION Callbacks[NOTIFY_SIZE];
  UINTN Action, Index, Calls = 0;
  Old = gBS->RaiseTPL (TPL_NOTIFY);
  if (mStopped) { gBS->RestoreTPL (Old); return; }
  if (!MyronKeyConfigValid (MmioRead32 (MYRON_KEY_CTL))) {
    mStopped = TRUE;
    mCount = 0;
    gBS->SetTimer (mPoll, TimerCancel, 0);
    DEBUG ((DEBUG_ERROR, "MYRON38: key input stopped; GPIO101 configuration changed\n"));
    gBS->RestoreTPL (Old);
    return;
  }
  Action = MyronKeySample (&mState, (MmioRead32 (MYRON_KEY_IO) & 1U) == 0,
                          GetTimeInNanoSecond (GetPerformanceCounter ()) / 1000000U);
  if (Action == MYRON_KEY_NONE || mCount == QUEUE_SIZE) {
    gBS->RestoreTPL (Old);
    return;
  }
  ZeroMem (&Key, sizeof (Key));
  if (Action == MYRON_KEY_NEXT) Key.Key.ScanCode = SCAN_DOWN;
  else Key.Key.UnicodeChar = CHAR_CARRIAGE_RETURN;
  Key.KeyState.KeyShiftState = EFI_SHIFT_STATE_VALID;
  Key.KeyState.KeyToggleState = EFI_TOGGLE_STATE_VALID;
  mQueue[(mHead + mCount) % QUEUE_SIZE] = Key;
  mCount++;
  gBS->SignalEvent (mInput.WaitForKey);
  gBS->SignalEvent (mInputEx.WaitForKeyEx);
  for (Index = 0; Index < NOTIFY_SIZE; Index++) {
    if (mNotify[Index].Function != NULL && Matches (&mNotify[Index].Key, &Key))
      Callbacks[Calls++] = mNotify[Index].Function;
  }
  DEBUG ((DEBUG_ERROR, "MYRON38: key release action=%u\n", (UINT32)Action));
  gBS->RestoreTPL (Old);
  /* Poll event runs at TPL_CALLBACK. No callbacks run inside the queue lock. */
  for (Index = 0; Index < Calls; Index++) Callbacks[Index] (&Key);
}

STATIC VOID EFIAPI
ExitBoot (EFI_EVENT Event, VOID *Context)
{
  mStopped = TRUE;
  mCount = 0;
  gBS->SetTimer (mPoll, TimerCancel, 0);
}

EFI_STATUS EFIAPI
MyronKeysEntry (EFI_HANDLE ImageHandle, EFI_SYSTEM_TABLE *SystemTable)
{
  EFI_STATUS Status;
  UINT32 Control = MmioRead32 (MYRON_KEY_CTL);
  if (!MyronKeyConfigValid (Control)) {
    DEBUG ((DEBUG_ERROR, "MYRON38: GPIO101 not inherited as GPIO input: %08x\n", Control));
    return EFI_UNSUPPORTED;
  }
  mInput.Reset = Reset;
  mInput.ReadKeyStroke = Read;
  mInputEx.Reset = ResetEx;
  mInputEx.ReadKeyStrokeEx = ReadEx;
  mInputEx.SetState = SetState;
  mInputEx.RegisterKeyNotify = RegisterNotify;
  mInputEx.UnregisterKeyNotify = UnregisterNotify;
  Status = gBS->CreateEvent (EVT_NOTIFY_WAIT, TPL_NOTIFY, WaitKey, NULL, &mInput.WaitForKey);
  if (EFI_ERROR (Status)) goto Fail;
  Status = gBS->CreateEvent (EVT_NOTIFY_WAIT, TPL_NOTIFY, WaitKey, NULL, &mInputEx.WaitForKeyEx);
  if (EFI_ERROR (Status)) goto Fail;
  Status = gBS->CreateEvent (EVT_TIMER | EVT_NOTIFY_SIGNAL, TPL_CALLBACK, Poll, NULL, &mPoll);
  if (EFI_ERROR (Status)) goto Fail;
  Status = gBS->CreateEventEx (EVT_NOTIFY_SIGNAL, TPL_NOTIFY, ExitBoot, NULL,
                             &gEfiEventExitBootServicesGuid, &mExit);
  if (EFI_ERROR (Status)) goto Fail;
  Status = gBS->SetTimer (mPoll, TimerPeriodic, EFI_TIMER_PERIOD_MILLISECONDS (20));
  if (EFI_ERROR (Status)) goto Fail;
  Status = gBS->InstallMultipleProtocolInterfaces (&mHandle,
                &gEfiDevicePathProtocolGuid, &KeypadDevicePath,
                &gEfiSimpleTextInProtocolGuid, &mInput,
                &gEfiSimpleTextInputExProtocolGuid, &mInputEx, NULL);
  if (EFI_ERROR (Status)) goto Fail;
  DEBUG ((DEBUG_ERROR, "MYRON38: GPIO101 read-only input installed; tap=next, hold-release=enter\n"));
  return EFI_SUCCESS;
Fail:
  mStopped = TRUE;
  if (mPoll != NULL) { gBS->SetTimer (mPoll, TimerCancel, 0); gBS->CloseEvent (mPoll); }
  if (mExit != NULL) gBS->CloseEvent (mExit);
  if (mInputEx.WaitForKeyEx != NULL) gBS->CloseEvent (mInputEx.WaitForKeyEx);
  if (mInput.WaitForKey != NULL) gBS->CloseEvent (mInput.WaitForKey);
  return Status;
}
