      "content": "/* SPDX-License-Identifier: BSD-2-Clause-Patent */
#include <PiPei.h>
#include <AdvancedLoggerInternal.h>
#include <Library/BaseMemoryLib.h>
#include <Library/HobLib.h>
#include <Library/MemoryAllocationLib.h>
#include <Library/MyronEarlyLogLib.h>
#include "AdvancedLoggerCommon.h"

#define EARLY_LOG_BYTES 0x10000
#define FINAL_LOG_BYTES 0x80000
/* A nonzero initializer gives this real, writable bytes in our SEC image.
 * No guessed physical address, heap, HOB, UART or DXE service is needed. */
STATIC UINT64 mEarlyLog[EARLY_LOG_BYTES / sizeof (UINT64)] = { 1 };
STATIC ADVANCED_LOGGER_INFO *mLog = NULL;
STATIC BOOLEAN mPublished;

VOID MyronEarlyLogInitialize (VOID)
{
  if (mLog != NULL) return;
  mLog = (ADVANCED_LOGGER_INFO *)mEarlyLog;
  ZeroMem ((VOID *)mLog, sizeof (*mLog));
  mLog->Version = ADVANCED_LOGGER_INFO_VER;
  mLog->LogBufferOffset = EXPECTED_LOG_BUFFER_OFFSET (mLog);
  mLog->LogCurrentOffset = mLog->LogBufferOffset;
  mLog->LogBufferSize = EARLY_LOG_BYTES - mLog->LogBufferOffset;
  mLog->HdwPortDisabled = TRUE;
  mLog->Signature = ADVANCED_LOGGER_SIGNATURE;
}

EFI_STATUS MyronEarlyLogPublish (VOID)
{
  ADVANCED_LOGGER_INFO *Copy;
  ADVANCED_LOGGER_PTR *Hob;
  UINT32 Used;
  if (mPublished) return EFI_SUCCESS;
  MyronEarlyLogInitialize ();
  Used = mLog->LogCurrentOffset;
  if (Used < mLog->LogBufferOffset || Used > EARLY_LOG_BYTES)
    return EFI_COMPROMISED_DATA;
  /* Called only after MemoryPeim: retain early records in reserved RAM,
   * so later driver/runtime logging never points back into boot-services FD. */
  Copy = AllocateReservedPages (EFI_SIZE_TO_PAGES (FINAL_LOG_BYTES));
  if (Copy == NULL) return EFI_OUT_OF_RESOURCES;
  CopyMem ((VOID *)Copy, (CONST VOID *)mLog, Used);
  Copy->LogBufferSize = FINAL_LOG_BYTES - Copy->LogBufferOffset;
  Copy->InPermanentRAM = TRUE;
  Hob = BuildGuidHob (&gAdvancedLoggerHobGuid, sizeof (*Hob));
  if (Hob == NULL) return EFI_OUT_OF_RESOURCES;
  Hob->Signature = ADVANCED_LOGGER_PTR_SIGNATURE;
  Hob->LogBuffer = (EFI_PHYSICAL_ADDRESS)(UINTN)Copy;
  mLog = Copy;
  mPublished = TRUE;
  return EFI_SUCCESS;
}

ADVANCED_LOGGER_INFO *EFIAPI AdvancedLoggerGetLoggerInfo (VOID)
{
  MyronEarlyLogInitialize ();
  return mLog;
}
UINT16 EFIAPI AdvancedLoggerGetPhase (VOID) { return ADVANCED_LOGGER_PHASE_SEC; }
BOOLEAN EFIAPI AdvancedLoggerPrintToHwPort (ADVANCED_LOGGER_INFO *Info, UINTN Level)
{
  return FALSE; /* Memory logging is real; no unverified UART access. */
}
