      "content": "/* SPDX-License-Identifier: BSD-2-Clause-Patent
 * R42: a bounded addition based on the R40 device log. Never recycle the
 * inherited heap or the Kernel arena. SEC maps this window without a HOB;
 * BDS may publish it only after validating the ORIGINAL bootloader FDT.
 * Reference: uefi-sheng 20ac23d5 ShengBootMemoryDxe (FDT/GCD intersection).
 */
#include <Uefi.h>
#include <Library/BaseMemoryLib.h>
#include <Library/DebugLib.h>
#include <Library/DxeServicesTableLib.h>
#include <Library/FdtLib.h>
#include <Library/HobLib.h>
#include <Library/MemoryAllocationLib.h>
#include <Library/MyronEntryLib.h>
#include <Library/UefiBootServicesTableLib.h>
#include <Protocol/GraphicsOutput.h>
#include "MemoryWindow.h"

STATIC EFI_MEMORY_DESCRIPTOR mWindowMap[512];

STATIC UINT64 WindowCells (CONST VOID *Data, UINT32 Count)
{
  CONST UINT8 *P = Data;
  UINT64 V = 0;
  for (UINT32 I = 0; I < Count * 4; I++) V = (V << 8) | P[I];
  return V;
}

STATIC BOOLEAN WindowOverlap (UINT64 Base, UINT64 Size)
{
  if (Size == 0) return FALSE;
  return Base > MAX_UINT64 - Size ||
    (Base < MYRON_WINDOW_END && Base + Size > MYRON_WINDOW_BASE);
}

STATIC UINT32 WindowCellCount (CONST VOID *Fdt, INT32 Node, CONST CHAR8 *Name)
{
  INT32 Len;
  CONST VOID *P = FdtGetProp (Fdt, Node, Name, &Len);
  if (P == NULL || Len != 4) return 0;
  UINT64 N = WindowCells (P, 1);
  return (N == 1 || N == 2) ? (UINT32)N : 0;
}

/* Linux v6.12 of_translate_dma_region uses the device's parent bus cells,
 * inherited from ancestors. Do not use the device's child-bus cell counts.
 * Require explicit counts (the root already has them), with bounded depth. */
STATIC UINT32 WindowBusCells (CONST VOID *Fdt, INT32 Device, CONST CHAR8 *Name)
{
  INT32 Node = FdtParentOffset (Fdt, Device), Len;
  for (UINT32 Depth = 0; Node >= 0 && Depth < 64; Depth++) {
    CONST VOID *P = FdtGetProp (Fdt, Node, Name, &Len);
    if (P != NULL) return WindowCellCount (Fdt, Node, Name);
    if (Len != -FDT_ERR_NOTFOUND) return 0;
    Node = FdtParentOffset (Fdt, Node);
  }
  return 0;
}

/* Legacy Linux v6.6 reserved-memory binding permits iommu-addresses without
 * reg: these reserve IOVA space, not physical RAM. Classify by validated
 * properties and phandles, never by a Qualcomm node name. No IOMMU is touched.
 * Called only when BOTH reg and size are absent, never for malformed values. */
STATIC BOOLEAN WindowIovaOnly (CONST VOID *Fdt, INT32 Node)
{
  INT32 Len, OtherLen;
  CONST CHAR8 *Reason = "missing-or-malformed-iommu-addresses";
  CONST UINT8 *P = FdtGetProp (Fdt, Node, "iommu-addresses", &Len);
  DEBUG ((DEBUG_ERROR, "MYRON42: reserved classification node=%a reg=absent size=absent iommu-bytes=%d\n",
          FdtGetName (Fdt, Node, NULL), Len));
  if (P == NULL || Len <= 0 || Len % 4 != 0 || Len > 4096) goto Refused;
  for (UINT32 I = 0; I < (UINT32)Len / 4 && I < 24; I++) {
    DEBUG ((DEBUG_ERROR, "MYRON42: iommu-cell[%u]=%lx\n", I, WindowCells (P + I * 4, 1)));
  }
  /* Physical allocation hints without size are ambiguous, not an IOVA pass. */
  Reason = "unexpected-physical-allocation-hint";
  if (FdtGetProp (Fdt, Node, "alloc-ranges", &OtherLen) != NULL || OtherLen != -FDT_ERR_NOTFOUND) goto Refused;
  if (FdtGetProp (Fdt, Node, "alignment", &OtherLen) != NULL || OtherLen != -FDT_ERR_NOTFOUND) goto Refused;
  UINT32 Offset = 0, Count = 0;
  while (Offset < (UINT32)Len) {
    Reason = "too-many-iova-tuples";
    if (++Count > 128) goto Refused;
    UINT32 Phandle = (UINT32)WindowCells (P + Offset, 1);
    Offset += 4;
    Reason = "unresolved-device-phandle";
    if (Phandle == 0 || Phandle == 0xFFFFFFFFU) goto Refused;
    INT32 Device = FdtNodeOffsetByPhandle (Fdt, Phandle);
    if (Device < 0) goto Refused;
    /* Linux can select a non-parent DMA bus via interconnects. This parser
     * deliberately refuses that topology instead of guessing tuple widths. */
    Reason = "unsupported-dma-parent-override";
    if (FdtGetProp (Fdt, Device, "interconnects", &OtherLen) != NULL || OtherLen != -FDT_ERR_NOTFOUND) goto Refused;
    UINT32 Ac = WindowBusCells (Fdt, Device, "#address-cells");
    UINT32 Sc = WindowBusCells (Fdt, Device, "#size-cells");
    DEBUG ((DEBUG_ERROR, "MYRON42: iommu-target phandle=%x node=%a ac=%u sc=%u\n",
            Phandle, FdtGetName (Fdt, Device, NULL), Ac, Sc));
    Reason = "invalid-bus-cells-or-truncated-tuple";
    if (Ac == 0 || Sc == 0 || (Ac + Sc) * 4 > (UINT32)Len - Offset) goto Refused;
    UINT64 Base = WindowCells (P + Offset, Ac);
    UINT64 Size = WindowCells (P + Offset + Ac * 4, Sc);
    Reason = "zero-or-overflowing-iova-range";
    if (Size == 0 || Base > MAX_UINT64 - Size) goto Refused;
    DEBUG ((DEBUG_ERROR, "MYRON42: IOVA tuple base=%lx size=%lx (not physical RAM)\n", Base, Size));
    Offset += (Ac + Sc) * 4;
  }
  DEBUG ((DEBUG_ERROR, "MYRON42: IOVA-only validated node=%a tuples=%u; no physical reservation\n",
          FdtGetName (Fdt, Node, NULL), Count));
  return TRUE;
Refused:
  DEBUG ((DEBUG_ERROR, "MYRON42: unresolved reserved node=%a reason=%a; no addition\n",
          FdtGetName (Fdt, Node, NULL), Reason));
  return FALSE;
}

/* Reject malformed/translated/incomplete descriptions. A size-only reserved
 * node is an OS allocation request, not a firmware physical allocation.
 * DTSpec 3.5.4: dynamic regions are allocated by the OS after boot services.
 * Validate their constraints, but do not treat possible placements as occupied. */
STATIC BOOLEAN WindowReg (CONST VOID *Fdt, INT32 Node, UINT32 Ac, UINT32 Sc,
                          BOOLEAN Ram, BOOLEAN *Covered)
{
  INT32 Len;
  UINT32 Width = (Ac + Sc) * 4;
  BOOLEAN Dynamic = FALSE;
  CONST UINT8 *P = FdtGetProp (Fdt, Node, "reg", &Len);
  if (P == NULL) {
    if (Ram || Len != -FDT_ERR_NOTFOUND) return FALSE;
    P = FdtGetProp (Fdt, Node, "size", &Len);
    if (P == NULL && Len == -FDT_ERR_NOTFOUND) return WindowIovaOnly (Fdt, Node);
    if (P == NULL || Len != (INT32)(Sc * 4)) {
      DEBUG ((DEBUG_ERROR, "MYRON42: unresolved reserved node=%a; no addition\n", FdtGetName (Fdt, Node, NULL)));
      return FALSE;
    }
    DEBUG ((DEBUG_ERROR, "MYRON42: dynamic OS request node=%a size=%lx\n",
            FdtGetName (Fdt, Node, NULL), WindowCells (P, Sc)));
    Dynamic = TRUE;
    P = FdtGetProp (Fdt, Node, "alloc-ranges", &Len);
    if (P == NULL) return Len == -FDT_ERR_NOTFOUND;
  }
  if (Len <= 0 || Len % Width != 0 || Len / Width > 128) return FALSE;
  for (UINT32 I = 0; I < (UINT32)Len; I += Width) {
    UINT64 Base = WindowCells (P + I, Ac);
    UINT64 Size = WindowCells (P + I + Ac * 4, Sc);
    if (Base > MAX_UINT64 - Size) return FALSE;
    if (Ram) {
      if (Base <= MYRON_WINDOW_BASE && Base + Size >= MYRON_WINDOW_END) *Covered = TRUE;
    } else if (!Dynamic && WindowOverlap (Base, Size)) {
      DEBUG ((DEBUG_ERROR, "MYRON42: reserved overlap node=%a base=%lx size=%lx\n", FdtGetName (Fdt, Node, NULL), Base, Size));
      return FALSE;
    }
  }
  return TRUE;
}

STATIC BOOLEAN WindowFdt (CONST VOID *Fdt)
{
  INT32 Root = FdtPathOffset (Fdt, "/"), Node, Reserved, Len;
  UINT32 Ac, Sc, Count;
  BOOLEAN Covered = FALSE;
  CONST VOID *P;
  if (Root < 0) return FALSE;
  Ac = WindowCellCount (Fdt, Root, "#address-cells");
  Sc = WindowCellCount (Fdt, Root, "#size-cells");
  if (Ac == 0 || Sc == 0) return FALSE;
  for (Node = FdtFirstSubnode (Fdt, Root), Count = 0; Node >= 0 && Count < 256;
       Node = FdtNextSubnode (Fdt, Node), Count++) {
    P = FdtGetProp (Fdt, Node, "device_type", &Len);
    if (P != NULL && Len == 7 && CompareMem (P, "memory", 7) == 0 &&
        !WindowReg (Fdt, Node, Ac, Sc, TRUE, &Covered)) return FALSE;
  }
  if (Node != -FDT_ERR_NOTFOUND || !Covered) return FALSE;
  Reserved = FdtPathOffset (Fdt, "/reserved-memory");
  if (Reserved < 0 || WindowCellCount (Fdt, Reserved, "#address-cells") != Ac ||
      WindowCellCount (Fdt, Reserved, "#size-cells") != Sc) return FALSE;
  P = FdtGetProp (Fdt, Reserved, "ranges", &Len);
  if (P == NULL || Len != 0) return FALSE;
  for (Node = FdtFirstSubnode (Fdt, Reserved), Count = 0; Node >= 0 && Count < 256;
       Node = FdtNextSubnode (Fdt, Node), Count++) {
    if (!WindowReg (Fdt, Node, Ac, Sc, FALSE, &Covered)) return FALSE;
  }
  if (Node != -FDT_ERR_NOTFOUND) return FALSE;
  INTN Reserves = FdtGetNumberOfReserveMapEntries (Fdt);
  if (Reserves < 0 || Reserves > 128) return FALSE;
  for (INTN I = 0; I < Reserves; I++) {
    UINT64 Base, Size;
    if (FdtGetReserveMapEntry (Fdt, I, &Base, &Size) != 0 || WindowOverlap (Base, Size)) return FALSE;
  }
  Node = FdtPathOffset (Fdt, "/chosen");
  if (Node == -FDT_ERR_NOTFOUND) return TRUE;
  if (Node < 0) return FALSE;
  INT32 EndLen;
  CONST VOID *End = FdtGetProp (Fdt, Node, "linux,initrd-end", &EndLen);
  P = FdtGetProp (Fdt, Node, "linux,initrd-start", &Len);
  if (P == NULL && End == NULL) return Len == -FDT_ERR_NOTFOUND && EndLen == -FDT_ERR_NOTFOUND;
  if (P == NULL || End == NULL || (Len != 4 && Len != 8) || (EndLen != 4 && EndLen != 8)) return FALSE;
  UINT64 Start = WindowCells (P, Len / 4), Stop = WindowCells (End, EndLen / 4);
  return Stop > Start && !WindowOverlap (Start, Stop - Start);
}

/* A map-only SEC entry must never be mistaken for firmware-owned free RAM. */
STATIC BOOLEAN WindowMaps (VOID)
{
  UINTN Size = sizeof (mWindowMap), Key, Stride = 0, Count;
  UINT32 Version;
  EFI_GCD_MEMORY_SPACE_DESCRIPTOR *Map = NULL;
  EFI_GRAPHICS_OUTPUT_PROTOCOL *Gop;
  EFI_STATUS Status;
  BOOLEAN Hole = FALSE;
  Status = gBS->GetMemoryMap (&Size, mWindowMap, &Key, &Stride, &Version);
  if (EFI_ERROR (Status) || Stride < sizeof (EFI_MEMORY_DESCRIPTOR) || Size == 0 || Size > sizeof (mWindowMap) || Size % Stride != 0) return FALSE;
  for (UINTN I = 0; I < Size; I += Stride) {
    EFI_MEMORY_DESCRIPTOR *D = (VOID *)((UINT8 *)mWindowMap + I);
    if (D->NumberOfPages > MAX_UINT64 / 4096 || WindowOverlap (D->PhysicalStart, D->NumberOfPages * 4096)) return FALSE;
  }
  if (EFI_ERROR (gBS->LocateProtocol (&gEfiGraphicsOutputProtocolGuid, NULL, (VOID **)&Gop)) ||
      Gop == NULL || Gop->Mode == NULL || Gop->Mode->FrameBufferSize == 0 || WindowOverlap (Gop->Mode->FrameBufferBase, Gop->Mode->FrameBufferSize)) return FALSE;
  Status = gDS->GetMemorySpaceMap (&Count, &Map);
  if (EFI_ERROR (Status)) return FALSE;
  if (Count > 2048 || Map == NULL) { if (Map != NULL) FreePool (Map); return FALSE; }
  for (UINTN I = 0; I < Count; I++) {
    if (Map[I].BaseAddress > MAX_UINT64 - Map[I].Length) { Hole = FALSE; break; }
    if (WindowOverlap (Map[I].BaseAddress, Map[I].Length)) {
      if (Map[I].GcdMemoryType != EfiGcdMemoryTypeNonExistent ||
          Map[I].BaseAddress > MYRON_WINDOW_BASE ||
          Map[I].BaseAddress + Map[I].Length < MYRON_WINDOW_END) { Hole = FALSE; break; }
      Hole = TRUE;
    }
  }
  FreePool (Map);
  return Hole;
}

VOID MyronAddBootMemory (VOID)
{
  VOID *Hob = GetFirstGuidHob (&gMyronBootEntryHobGuid);
  MYRON_BOOT_ENTRY Entry;
  CONST VOID *Fdt;
  EFI_STATUS Status;
  EFI_PHYSICAL_ADDRESS Probe = MYRON_WINDOW_BASE;
  DEBUG ((DEBUG_ERROR, "MYRON42: MEMORY BEGIN base=%lx size=%lx\n", MYRON_WINDOW_BASE, MYRON_WINDOW_SIZE));
  if (Hob == NULL || GET_GUID_HOB_DATA_SIZE (Hob) != sizeof (Entry)) goto Refused;
  CopyMem (&Entry, GET_GUID_HOB_DATA (Hob), sizeof (Entry));
  if (Entry.Magic != MYRON_ENTRY_MAGIC || Entry.Version != MYRON_ENTRY_VERSION || Entry.Size != sizeof (Entry) ||
      (Entry.X0 & 7) != 0 || Entry.X0 < 0xC7800000ULL || Entry.X0 > 0xD7800000ULL - 40) goto Refused;
  Fdt = (CONST VOID *)(UINTN)Entry.X0;
  if (FdtCheckHeader (Fdt) != 0 || FdtTotalSize (Fdt) < 40 || FdtTotalSize (Fdt) > 0x200000 ||
      FdtTotalSize (Fdt) > 0xD7800000ULL - Entry.X0 || !WindowFdt (Fdt)) goto Refused;
  if (!WindowMaps ()) goto Refused;
  /* This range is already WB/XN mapped by SEC, before publication. AddMemorySpace
   * itself exposes conventional pages; do not defer MMU mapping until after it. */
  Status = gDS->AddMemorySpace (EfiGcdMemoryTypeSystemMemory, MYRON_WINDOW_BASE,
                              MYRON_WINDOW_SIZE, EFI_MEMORY_WB);
  DEBUG ((DEBUG_ERROR, "MYRON42: add pre-mapped window status=%r\n", Status));
  if (EFI_ERROR (Status)) return;
  Status = gDS->SetMemorySpaceAttributes (MYRON_WINDOW_BASE, MYRON_WINDOW_SIZE, EFI_MEMORY_WB);
  DEBUG ((DEBUG_ERROR, "MYRON42: confirm-WB-attributes status=%r\n", Status));
  if (EFI_ERROR (Status)) return;
  Status = gBS->AllocatePages (AllocateAddress, EfiLoaderData, 0x80000, &Probe);
  DEBUG ((DEBUG_ERROR, "MYRON42: allocate-2GiB base=%lx status=%r\n", Probe, Status));
  if (!EFI_ERROR (Status)) {
    /* Bounded access check, not a complete RAM or DMA-coherency test. */
    volatile UINT64 *First = (VOID *)(UINTN)Probe;
    volatile UINT64 *Last = (VOID *)(UINTN)(Probe + 0x80000000 - sizeof (UINT64));
    *First = 0x4D59524F4E343200ULL; *Last = ~0x4D59524F4E343200ULL;
    BOOLEAN Ok = *First == 0x4D59524F4E343200ULL && *Last == ~0x4D59524F4E343200ULL;
    *First = 0; *Last = 0;
    DEBUG ((DEBUG_ERROR, "MYRON42: endpoint-access=%u (not full RAM test)\n", Ok));
    Status = gBS->FreePages (Probe, 0x80000);
    DEBUG ((DEBUG_ERROR, "MYRON42: free-2GiB status=%r\n", Status));
  }
  DEBUG ((DEBUG_ERROR, "MYRON42: MEMORY END; XNU not loaded by memory test\n"));
  return;
Refused:
  DEBUG ((DEBUG_ERROR, "MYRON42: MEMORY REFUSED; original FDT/reservations/GCD/EFI/GOP not proven; menu continues\n"));
}
