STATIC EFI_STATUS EFIAPI EmbeddedReset (EFI_BLOCK_IO_PROTOCOL *This, BOOLEAN Extended)
{ return EFI_SUCCESS; }
STATIC EFI_STATUS EFIAPI EmbeddedBlockRead (EFI_BLOCK_IO_PROTOCOL *This, UINT32 MediaId,
                                           EFI_LBA Lba, UINTN Size, VOID *Buffer)
{
  if (!mEmbeddedReady) return EFI_NOT_READY;
  if (Buffer == NULL) return EFI_INVALID_PARAMETER;
  if (MediaId != mEmbeddedMedia.MediaId) return EFI_MEDIA_CHANGED;
  if (Size % 512 != 0) return EFI_BAD_BUFFER_SIZE;
  if (Lba > mEmbeddedMedia.LastBlock || Size / 512 > mEmbeddedMedia.LastBlock + 1 - Lba) return EFI_INVALID_PARAMETER;
  return EmbeddedRead (mEmbeddedPayload, Lba * 512, Size, Buffer) ? EFI_SUCCESS : EFI_INVALID_PARAMETER;
}
STATIC EFI_STATUS EFIAPI EmbeddedBlockWrite (EFI_BLOCK_IO_PROTOCOL *This, UINT32 MediaId,
                                            EFI_LBA Lba, UINTN Size, VOID *Buffer)
{ return EFI_WRITE_PROTECTED; }
STATIC EFI_STATUS EFIAPI EmbeddedFlush (EFI_BLOCK_IO_PROTOCOL *This)
{ return EFI_SUCCESS; }
