  EFI_BLOCK_IO_PROTOCOL_REVISION, &mEmbeddedMedia,
  EmbeddedReset, EmbeddedBlockRead, EmbeddedBlockWrite, EmbeddedFlush
};

/* Accept the configuration only from this device path, never another volume.
 * Reading expected+1 bytes detects appended data without trusting file sizes. */
STATIC VOID EmbeddedCheckFileSystem (VOID)
{
  EFI_HANDLE *Handles = NULL;
  UINTN Count = 0;
  EFI_STATUS Status = gBS->LocateHandleBuffer (ByProtocol, &gEfiSimpleFileSystemProtocolGuid, NULL, &Count, &Handles);
  DEBUG ((DEBUG_ERROR, "MYRON44: filesystem handles status=%r count=%u\n", Status, Count));
  if (EFI_ERROR (Status)) return;
  if (Count > 256) { FreePool (Handles); return; }
  BOOLEAN Matched = FALSE;
  for (UINTN I = 0; I < Count; I++) {
    EFI_DEVICE_PATH_PROTOCOL *Path;
    EFI_SIMPLE_FILE_SYSTEM_PROTOCOL *Fs;
    EFI_FILE_PROTOCOL *Root = NULL, *File = NULL;
    if (EFI_ERROR (gBS->HandleProtocol (Handles[I], &gEfiDevicePathProtocolGuid, (VOID **)&Path)) ||
        Path == NULL || DevicePathNodeLength (Path) != sizeof (VENDOR_DEVICE_PATH) ||
        CompareMem (Path, &mEmbeddedPath.Vendor, sizeof (VENDOR_DEVICE_PATH)) != 0) continue;
    if (EFI_ERROR (gBS->HandleProtocol (Handles[I], &gEfiSimpleFileSystemProtocolGuid, (VOID **)&Fs))) continue;
    Status = Fs->OpenVolume (Fs, &Root);
    if (!EFI_ERROR (Status)) Status = Root->Open (Root, &File, L"\\EFI\\UniXNU\\unixnu.toml", EFI_FILE_MODE_READ, 0);
    UINT8 Data[sizeof (mEmbeddedConfig) + 1];
    UINTN Size = sizeof (Data);
    if (!EFI_ERROR (Status)) Status = File->Read (File, &Size, Data);
    BOOLEAN Exact = !EFI_ERROR (Status) && Size == sizeof (mEmbeddedConfig) && CompareMem (Data, mEmbeddedConfig, Size) == 0;
    DEBUG ((DEBUG_ERROR, "MYRON44: embedded config read status=%r bytes=%u exact=%u\n", Status, Size, Exact));
    if (File != NULL) File->Close (File);
    if (Root != NULL) Root->Close (Root);
    if (Exact) { Matched = TRUE; break; }
  }
  FreePool (Handles);
  DEBUG ((DEBUG_ERROR, "MYRON44: filesystem-config-verified=%u\n", Matched));
}

STATIC VOID EmbeddedLogMemory (VOID)
{
  STATIC EFI_MEMORY_DESCRIPTOR Map[512];
  UINTN Size = sizeof (Map), Key, Stride = 0;
  UINT32 Version;
  UINT64 Largest = 0;
  EFI_STATUS Status = gBS->GetMemoryMap (&Size, Map, &Key, &Stride, &Version);
  if (!EFI_ERROR (Status) && Size > 0 && Size <= sizeof (Map) && Stride >= sizeof (EFI_MEMORY_DESCRIPTOR) && Size % Stride == 0) {
    for (UINTN I = 0; I < Size; I += Stride) {
      EFI_MEMORY_DESCRIPTOR *D = (VOID *)((UINT8 *)Map + I);
      if (D->Type == EfiConventionalMemory && D->NumberOfPages <= MAX_UINT64 / 4096 && D->NumberOfPages * 4096 > Largest)
        Largest = D->NumberOfPages * 4096;
    }
  }
  DEBUG ((DEBUG_ERROR, "MYRON44: post-payload memory status=%r largest=%lx window256=%u\n", Status, Largest, Largest >= 0x10000000));
}

/* Only SEC can produce this marker in the sanitized copy; it first removes
 * any same-named property from the original. A refused transport keeps R44. */
STATIC BOOLEAN KernelPayloadPublished (VOID)
{
  STATIC CONST EFI_GUID Guid = {0xdaee82e6,0x8090,0x4e72,{0xbf,0xb9,0x78,0xc1,0x3c,0xd4,0xe3,0x59}};
  VOID *Hob = GetFirstGuidHob (&Guid);
  UINT64 Address;
  INT32 Length, Node;
  CONST UINT8 *Value;
  if (Hob == NULL || GET_GUID_HOB_DATA_SIZE (Hob) != sizeof (Address)) return FALSE;
  CopyMem (&Address, GET_GUID_HOB_DATA (Hob), sizeof (Address));
  if (Address == 0 || FdtCheckHeader ((VOID *)(UINTN)Address) != 0) return FALSE;
  Node = FdtPathOffset ((VOID *)(UINTN)Address, "/chosen");
  if (Node < 0) return FALSE;
  Value = FdtGetProp ((VOID *)(UINTN)Address, Node, "myron,r48-payload-crc32", &Length);
  return Value != NULL && Length == 4 &&
    (((UINT32)Value[0] << 24) | ((UINT32)Value[1] << 16) | ((UINT32)Value[2] << 8) | Value[3]) == MYRON_KERNEL_FAT_CRC32;
}

VOID MyronPublishEmbeddedPayload (VOID)
{
  if (KernelPayloadPublished ()) {
    DEBUG ((DEBUG_ERROR, "MYRON48: verified kernel FAT selected; R44 fallback not installed\n"));
    EmbeddedLogMemory ();
    return;
  }
  if (mEmbeddedHandle != NULL) return;
  DEBUG ((DEBUG_ERROR, "MYRON44: EMBEDDED BEGIN stored=%u logical=%u sha256=%a\n",
          sizeof (mEmbeddedPayload), MYRON_EMBEDDED_BYTES, MYRON_EMBEDDED_SHA256));
  if (!EmbeddedValidate (mEmbeddedPayload, sizeof (mEmbeddedPayload), MYRON_EMBEDDED_CRC32)) {
    DEBUG ((DEBUG_ERROR, "MYRON44: embedded validation refused; menu continues\n")); return;
  }
  mEmbeddedMedia.MediaId = 44;
  mEmbeddedMedia.MediaPresent = TRUE;
  mEmbeddedMedia.ReadOnly = TRUE;
  mEmbeddedMedia.BlockSize = 512;
  mEmbeddedMedia.IoAlign = 1;
  mEmbeddedMedia.LastBlock = MYRON_EMBEDDED_BYTES / 512 - 1;
  mEmbeddedReady = TRUE;
  EFI_STATUS Status = gBS->InstallMultipleProtocolInterfaces (&mEmbeddedHandle,
                      &gEfiDevicePathProtocolGuid, &mEmbeddedPath,
                      &gEfiBlockIoProtocolGuid, &mEmbeddedBlock, NULL);
  DEBUG ((DEBUG_ERROR, "MYRON44: embedded BlockIO install status=%r read-only=1\n", Status));
  if (EFI_ERROR (Status)) { mEmbeddedReady = FALSE; mEmbeddedHandle = NULL; return; }
  Status = gBS->ConnectController (mEmbeddedHandle, NULL, NULL, TRUE);
  DEBUG ((DEBUG_ERROR, "MYRON44: embedded ConnectController status=%r\n", Status));
  EmbeddedCheckFileSystem ();
  EmbeddedLogMemory ();
  DEBUG ((DEBUG_ERROR, "MYRON44: EMBEDDED END; no XNU kernel included\n"));
}
