      "content": "/* SPDX-License-Identifier: BSD-2-Clause-Patent */
#ifndef MYRON_EMBEDDED_PAYLOAD_POLICY_H
#define MYRON_EMBEDDED_PAYLOAD_POLICY_H
#define MYRON_EMBEDDED_BYTES 0x4000000U
STATIC UINT32 EmbeddedU32 (CONST UINT8 *P)
{
  return (UINT32)P[0] | ((UINT32)P[1] << 8) | ((UINT32)P[2] << 16) | ((UINT32)P[3] << 24);
}
STATIC BOOLEAN EmbeddedValidate (CONST UINT8 *P, UINTN Size, UINT32 Crc)
{
  if (P == NULL || Size < 32 || Size > 0x100000 || CompareMem (P, "MYSFAT44", 8) != 0 ||
      EmbeddedU32 (P + 8) != MYRON_EMBEDDED_BYTES || EmbeddedU32 (P + 16) != Size ||
      EmbeddedU32 (P + 20) != 0 || EmbeddedU32 (P + 24) != 0 || EmbeddedU32 (P + 28) != 0) return FALSE;
  UINT32 Count = EmbeddedU32 (P + 12);
  if (Count == 0 || Count > 128 || 32 + Count * 12 > Size) return FALSE;
  UINT32 EndSector = 0, EndData = 32 + Count * 12;
  for (UINT32 I = 0; I < Count; I++) {
    CONST UINT8 *E = P + 32 + I * 12;
    UINT32 Sector = EmbeddedU32 (E), Sectors = EmbeddedU32 (E + 4), Data = EmbeddedU32 (E + 8);
    if (Sector < EndSector || Sector >= MYRON_EMBEDDED_BYTES / 512 || Sectors == 0 ||
        Sectors > MYRON_EMBEDDED_BYTES / 512 - Sector || Data != EndData ||
        Data > Size || Sectors > (Size - Data) / 512) return FALSE;
    EndSector = Sector + Sectors; EndData = Data + Sectors * 512;
  }
  return EndData == Size && CalculateCrc32 ((VOID *)(UINTN)P, Size) == Crc;
}
/* Only use after EmbeddedValidate. P is immutable firmware data, retained for
 * the entire Block I/O lifetime. Missing extents are zero-filled sectors. */
STATIC BOOLEAN EmbeddedRead (CONST UINT8 *P, UINT64 Offset, UINTN Size, VOID *Buffer)
{
  if (Buffer == NULL || Offset > MYRON_EMBEDDED_BYTES || Size > MYRON_EMBEDDED_BYTES - Offset) return FALSE;
  ZeroMem (Buffer, Size);
  UINT64 End = Offset + Size;
  for (UINT32 I = 0; I < EmbeddedU32 (P + 12); I++) {
    CONST UINT8 *E = P + 32 + I * 12;
    UINT64 First = (UINT64)EmbeddedU32 (E) * 512;
    UINT64 Last = First + (UINT64)EmbeddedU32 (E + 4) * 512;
    UINT64 Begin = Offset > First ? Offset : First;
    UINT64 Stop = End < Last ? End : Last;
    if (Begin < Stop) CopyMem ((UINT8 *)Buffer + (UINTN)(Begin - Offset),
                              P + EmbeddedU32 (E + 8) + (UINTN)(Begin - First), (UINTN)(Stop - Begin));
  }
  return TRUE;
}
