STATIC CONST EFI_GUID mAuditFdtGuid = {
  0xdaee82e6, 0x8090, 0x4e72, {0xbf,0xb9,0x78,0xc1,0x3c,0xd4,0xe3,0x59}
};
STATIC EFI_MEMORY_DESCRIPTOR mAuditMap[512];

STATIC UINT64 AuditCells (CONST VOID *Data, UINT32 Count)
{
  CONST UINT8 *P = Data;
  UINT64 Value = 0;
  for (UINT32 I = 0; I < Count * 4; I++) Value = (Value << 8) | P[I];
  return Value;
}

STATIC UINT32 CellCount (CONST VOID *Fdt, INT32 Node, CONST CHAR8 *Name, UINT32 Default)
{
  INT32 Length;
  CONST VOID *P = FdtGetProp (Fdt, Node, Name, &Length);
  if (P == NULL) return Default;
  if (Length != 4) return 0;
  return (UINT32)AuditCells (P, 1);
}

STATIC VOID AuditReg (CONST VOID *Fdt, INT32 Node, UINT32 Ac, UINT32 Sc, CONST CHAR8 *Kind)
{
  INT32 Length, NameLength;
  CONST UINT8 *Reg = FdtGetProp (Fdt, Node, "reg", &Length);
  CONST CHAR8 *Name = FdtGetName (Fdt, Node, &NameLength);
  UINT32 Width = (Ac + Sc) * 4;
  if (Reg == NULL) {
    DEBUG ((DEBUG_ERROR, "MYRON40: DT %a node=%a no-reg (dynamic/unresolved)\n", Kind, Name));
    return;
  }
  if ((Ac != 1 && Ac != 2) || (Sc != 1 && Sc != 2) ||
      Length <= 0 || Length % Width != 0 || Length / Width > 128) {
    DEBUG ((DEBUG_ERROR, "MYRON40: DT %a malformed-reg node=%a\n", Kind, Name));
    return;
  }
  for (UINT32 Offset = 0; Offset < (UINT32)Length; Offset += Width) {
    UINT64 Base = AuditCells (Reg + Offset, Ac);
    UINT64 Size = AuditCells (Reg + Offset + Ac * 4, Sc);
    DEBUG ((DEBUG_ERROR, "MYRON40: DT %a node=%a base=%lx size=%lx valid=%u\n",
            Kind, Name, Base, Size, Size != 0 && Base <= MAX_UINT64 - Size));
  }
}

STATIC VOID AuditFdt (VOID)
{
  VOID *Hob = GetFirstGuidHob (&mAuditFdtGuid);
  UINT64 Address;
  CONST VOID *Fdt;
  INT32 Root, Node, Reserved;
  UINT32 Ac, Sc, Rac, Rsc, Count;
  INTN Reserves;
  if (Hob == NULL || GET_GUID_HOB_DATA_SIZE (Hob) != sizeof (Address)) {
    DEBUG ((DEBUG_ERROR, "MYRON40: DT unavailable: no copied FDT HOB\n"));
    return;
  }
  CopyMem (&Address, GET_GUID_HOB_DATA (Hob), sizeof (Address));
  Fdt = (CONST VOID *)(UINTN)Address;
  if (Address == 0 || FdtCheckHeader (Fdt) != 0) return;
  Root = FdtPathOffset (Fdt, "/");
  if (Root < 0) return;
  Ac = CellCount (Fdt, Root, "#address-cells", 2);
  Sc = CellCount (Fdt, Root, "#size-cells", 1);
  DEBUG ((DEBUG_ERROR, "MYRON40: DT root-cells=%u/%u\n", Ac, Sc));
  for (Node = FdtFirstSubnode (Fdt, Root), Count = 0; Node >= 0 && Count < 256;
       Node = FdtNextSubnode (Fdt, Node), Count++) {
    INT32 Length;
    CONST VOID *Type = FdtGetProp (Fdt, Node, "device_type", &Length);
    if (Type != NULL && Length == 7 && CompareMem (Type, "memory", 7) == 0)
      AuditReg (Fdt, Node, Ac, Sc, "ram");
  }
  if (Node != -FDT_ERR_NOTFOUND) DEBUG ((DEBUG_ERROR, "MYRON40: DT root walk incomplete=%d\n", Node));
  Reserved = FdtPathOffset (Fdt, "/reserved-memory");
  if (Reserved >= 0) {
    Rac = CellCount (Fdt, Reserved, "#address-cells", Ac);
    Rsc = CellCount (Fdt, Reserved, "#size-cells", Sc);
    for (Node = FdtFirstSubnode (Fdt, Reserved), Count = 0; Node >= 0 && Count < 256;
         Node = FdtNextSubnode (Fdt, Node), Count++) AuditReg (Fdt, Node, Rac, Rsc, "reserved");
    if (Node != -FDT_ERR_NOTFOUND) DEBUG ((DEBUG_ERROR, "MYRON40: DT reserved walk incomplete=%d\n", Node));
  }
  Reserves = FdtGetNumberOfReserveMapEntries (Fdt);
  DEBUG ((DEBUG_ERROR, "MYRON40: DT memreserve-count=%d\n", Reserves));
  if (Reserves < 0 || Reserves > 128) return;
  for (INTN I = 0; I < Reserves; I++) {
    UINT64 Base, Size;
    if (FdtGetReserveMapEntry (Fdt, I, &Base, &Size) != 0) return;
    DEBUG ((DEBUG_ERROR, "MYRON40: DT memreserve base=%lx size=%lx\n", Base, Size));
  }
}

VOID MyronAuditHandoff (VOID)
{
  EFI_STATUS Status;
  UINTN Size = sizeof (mAuditMap), Key, Stride = 0, Count;
  UINT32 Version;
  UINT64 Largest = 0, FreeBytes = 0;
  EFI_GCD_MEMORY_SPACE_DESCRIPTOR *Gcd = NULL;
  EFI_GRAPHICS_OUTPUT_PROTOCOL *Gop;
  DEBUG ((DEBUG_ERROR, "MYRON40: AUDIT BEGIN after-R42-bounded-memory-attempt\n"));
  AuditFdt ();
  Status = gBS->GetMemoryMap (&Size, mAuditMap, &Key, &Stride, &Version);
  DEBUG ((DEBUG_ERROR, "MYRON40: EFI-map status=%r bytes=%lu stride=%lu\n", Status, (UINT64)Size, (UINT64)Stride));
  if (!EFI_ERROR (Status) && Stride >= sizeof (EFI_MEMORY_DESCRIPTOR) && Size % Stride == 0 && Size <= sizeof (mAuditMap)) {
    for (UINTN Offset = 0; Offset < Size; Offset += Stride) {
      EFI_MEMORY_DESCRIPTOR *D = (VOID *)((UINT8 *)mAuditMap + Offset);
      DEBUG ((DEBUG_ERROR, "MYRON40: EFI type=%u base=%lx pages=%lx attr=%lx\n",
              D->Type, D->PhysicalStart, D->NumberOfPages, D->Attribute));
      if (D->Type == EfiConventionalMemory && D->NumberOfPages <= MAX_UINT64 / 4096) {
        UINT64 Bytes = D->NumberOfPages * 4096;
        if (Bytes > Largest) Largest = Bytes;
        if (FreeBytes <= MAX_UINT64 - Bytes) FreeBytes += Bytes;
      }
    }
  }
  DEBUG ((DEBUG_ERROR, "MYRON40: EFI conventional-total=%lx largest-descriptor=%lx requested-window=10000000\n", FreeBytes, Largest));
  Status = gDS->GetMemorySpaceMap (&Count, &Gcd);
  DEBUG ((DEBUG_ERROR, "MYRON40: GCD-map status=%r\n", Status));
  if (!EFI_ERROR (Status) && Gcd != NULL) {
    if (Count <= 512) {
      for (UINTN I = 0; I < Count; I++)
        DEBUG ((DEBUG_ERROR, "MYRON40: GCD type=%u base=%lx size=%lx cap=%lx attr=%lx\n",
                Gcd[I].GcdMemoryType, Gcd[I].BaseAddress, Gcd[I].Length,
                Gcd[I].Capabilities, Gcd[I].Attributes));
    } else DEBUG ((DEBUG_ERROR, "MYRON40: GCD-map truncated count=%lu\n", (UINT64)Count));
    FreePool (Gcd);
  }
  Status = gBS->LocateProtocol (&gEfiGraphicsOutputProtocolGuid, NULL, (VOID **)&Gop);
  if (!EFI_ERROR (Status) && Gop->Mode != NULL && Gop->Mode->Info != NULL)
    DEBUG ((DEBUG_ERROR, "MYRON40: GOP base=%lx size=%lx width=%u height=%u stride=%u format=%u\n",
            Gop->Mode->FrameBufferBase, (UINT64)Gop->Mode->FrameBufferSize,
            Gop->Mode->Info->HorizontalResolution, Gop->Mode->Info->VerticalResolution,
            Gop->Mode->Info->PixelsPerScanLine, Gop->Mode->Info->PixelFormat));
  DEBUG ((DEBUG_ERROR, "MYRON40: AUDIT END; export Tools/Advanced Logger before reset\n"));
}
