// No ConOut, font protocol, allocation or device connection is required. The
// same GOP BLT path already draws the fourth (green) pre-console stripe.
STATIC volatile UINT16 mBdsPhase;
STATIC VOID MyronBdsPhase (UINT16 Code)
{
  STATIC CONST UINT8 Font[16][5] = {
    {7,5,5,5,7}, {2,6,2,2,7}, {7,1,7,4,7}, {7,1,7,1,7},
    {5,5,7,1,1}, {7,4,7,1,7}, {7,4,7,5,7}, {7,1,1,1,1},
    {7,5,7,5,7}, {7,5,7,1,7}, {2,5,7,5,5}, {6,5,6,5,6},
    {7,4,4,4,7}, {6,5,5,5,6}, {7,4,6,4,7}, {7,4,6,4,4}
  };
  EFI_GRAPHICS_OUTPUT_PROTOCOL *Gop = NULL;
  EFI_GRAPHICS_OUTPUT_BLT_PIXEL Black = {0,0,0,0};
  EFI_GRAPHICS_OUTPUT_BLT_PIXEL White = {255,255,255,0};
  UINTN Digit, Row, Col;
  mBdsPhase = Code;
  if (EFI_ERROR (gBS->LocateProtocol (&gEfiGraphicsOutputProtocolGuid, NULL, (VOID **)&Gop)) ||
      Gop == NULL || Gop->Blt == NULL || Gop->Mode == NULL || Gop->Mode->Info == NULL ||
      Gop->Mode->Info->HorizontalResolution < 288 ||
      Gop->Mode->Info->VerticalResolution < 288) return;
  // Four 3x5 digits at 16x scale: 240 px wide, 80 px high, below old stripes.
  if (EFI_ERROR (Gop->Blt (Gop, &Black, EfiBltVideoFill, 0, 0, 32, 208, 256, 80, 0))) return;
  for (Digit = 0; Digit < 4; Digit++) {
    UINTN Value = (Code >> ((3 - Digit) * 4)) & 15;
    for (Row = 0; Row < 5; Row++) {
      for (Col = 0; Col < 3; Col++) {
        if (Font[Value][Row] & (1U << (2 - Col))) {
          if (EFI_ERROR (Gop->Blt (Gop, &White, EfiBltVideoFill, 0, 0,
                         32 + Digit * 64 + Col * 16, 208 + Row * 16, 16, 16, 0))) return;
        }
      }
    }
  }
}
#else
#define MyronBdsPhase(Code) ((VOID)0)
#endif

