VOID EFIAPI PlatformBootManagerBeforeConsole (VOID)
{
#if MYRON_MINIMAL
  EFI_GRAPHICS_OUTPUT_PROTOCOL *Gop;
  EFI_GRAPHICS_OUTPUT_BLT_PIXEL Green = {0,255,0,0};
  if (!EFI_ERROR (gBS->LocateProtocol (&gEfiGraphicsOutputProtocolGuid, NULL, (VOID **)&Gop)) &&
      Gop->Mode != NULL && Gop->Mode->Info != NULL && Gop->Mode->Info->VerticalResolution >= 184) {
    Gop->Blt (Gop, &Green, EfiBltVideoFill, 0, 0, 0, 168,
              Gop->Mode->Info->HorizontalResolution, 16, 0);
  }
  DEBUG ((DEBUG_ERROR, "MYRON38: BDS before-console reached\n"));
#endif
  MyronBdsPhase (0xB001); // About to signal EndOfDxe.
  EfiEventGroupSignal (&gEfiEndOfDxeEventGroupGuid);
  MyronBdsPhase (0xB002); // About to dispatch deferred images.
  EfiBootManagerDispatchDeferredImages ();
#if MYRON_MINIMAL
  MyronBdsPhase (0xB003);
  EfiBootManagerUpdateConsoleVariable (ConIn, (EFI_DEVICE_PATH_PROTOCOL *)&KeypadDevicePath, NULL);
  MyronBdsPhase (0xB004);
  EfiBootManagerUpdateConsoleVariable (ConOut, (EFI_DEVICE_PATH_PROTOCOL *)&DisplayDevicePath, NULL);
  MyronBdsPhase (0xB005);
  EfiBootManagerUpdateConsoleVariable (ErrOut, (EFI_DEVICE_PATH_PROTOCOL *)&DisplayDevicePath, NULL);
#endif
  MyronBdsPhase (0xB006); // Returned to BDS; console connection follows.
}

VOID EFIAPI PlatformBootManagerAfterConsole (VOID)
{
  EFI_STATUS Status;
#if !MYRON_MINIMAL
  EFI_EVENT Event;
#endif
  VOID *Hob;
  if (mStarted) return;
  mStarted = TRUE;
  MyronBdsPhase (0xB010); // AfterConsole reached; before entry-record publication.
  Hob = GetFirstGuidHob (&gMyronBootEntryHobGuid);
  if (Hob != NULL && GET_GUID_HOB_DATA_SIZE(Hob) == sizeof(MYRON_BOOT_ENTRY)) {
    Status = gBS->InstallConfigurationTable (&gMyronBootEntryHobGuid, GET_GUID_HOB_DATA(Hob));
    if (EFI_ERROR(Status)) Print (L"MYRON entry record publication failed: %r\r\n", Status);
  }
  /* Run from BDS at TPL_APPLICATION, after driver dispatch. */
  DEBUG ((DEBUG_ERROR, "MYRON17: BDS ConnectAll begin\n"));
  MyronBdsPhase (0xB011);
  EfiBootManagerConnectAll ();
  DEBUG ((DEBUG_ERROR, "MYRON17: BDS ConnectAll done\n"));
#if MYRON_MINIMAL
  MyronBdsPhase (0xB012);
  MyronAddBootMemory ();
  MyronBdsPhase (0xB013);
  MyronAuditHandoff ();
  MyronBdsPhase (0xB014);
