VOID MyronCaptureStockDisplay (VOID)
{
  // Own xbl_config DXE_Heap only. Called BEFORE HobConstructor/MemoryPeim;
  // minimal also reserves that old heap. Excludes MMIO, secure carveouts, FD,
  // stack and Android kernel payload.
  MyronFindStockDisplay ((CONST VOID *)(UINTN)0xB00F0000ULL, 0x131A0000, 0xB00F0000ULL, &mMyronDisplay);
