    mMyronDisplay.Width, mMyronDisplay.Height, mMyronDisplay.Stride));
}

VOID MyronPaintDisplayStage (UINT32 Stage)
{
  UINT32 Y, X, First = 96 + Stage * 24;
  volatile UINT32 *Pixels;
  if (mMyronDisplay.Status != 1 || Stage > 1 || mMyronDisplay.Height < First + 16) return;
  Pixels = (volatile UINT32 *)(UINTN)mMyronDisplay.Base;
  for (Y = First; Y < First + 16; Y++) {
    for (X = 0; X < mMyronDisplay.Width; X++)
      Pixels[Y * (mMyronDisplay.Stride / 4) + X] = Stage == 0 ? 0x0000FFFFU : 0x00FF00FFU;
  }
  WriteBackDataCacheRange ((VOID *)(UINTN)(mMyronDisplay.Base + (UINT64)First * mMyronDisplay.Stride),
                          (UINTN)16 * mMyronDisplay.Stride);
