STATIC UINT32 Le32 (CONST UINT8 *P) {
  return (UINT32)P[0] | ((UINT32)P[1] << 8) | ((UINT32)P[2] << 16) | ((UINT32)P[3] << 24);
}
STATIC UINT64 Le64 (CONST UINT8 *P) { return Le32 (P) | ((UINT64)Le32 (P + 4) << 32); }
STATIC UINT32 Crc (CONST UINT8 *P, UINTN N) {
  UINT32 V = 0xFFFFFFFFU;
  while (N--) {
    V ^= *P++;
    for (UINTN I = 0; I < 8; I++) V = (V >> 1) ^ ((0U - (V & 1)) & 0xEDB88320U);
  }
  return ~V;
}

EFI_STATUS MyronValidateStockDisplay (CONST VOID *Image, UINTN Size, UINT64 LoadedBase,
                                     MYRON_DISPLAY_HANDOFF *Out)
{
  CONST UINT8 *P = Image;
  UINT32 W, H, Pitch, MaxMode, Mode;
  UINT64 Base, Bytes, Extent;
  if (Out == NULL) return EFI_INVALID_PARAMETER;
  ZeroMem (Out, sizeof (*Out));
  if (P == NULL || Size < MYRON_STOCK_DISPLAY_SIZE || (LoadedBase & 0xFFF) ||
      LoadedBase > MAX_UINT64 - MYRON_STOCK_DISPLAY_SIZE) return EFI_INVALID_PARAMETER;
  if (P[0] != 'M' || P[1] != 'Z' || Le32 (P + 0x3C) != 0xE58 ||
      Le32 (P + 0xE58) != 0x4550 || Le32 (P + 0xE5C) != 0x0003AA64 ||
      Le32 (P + 0xEA8) != MYRON_STOCK_DISPLAY_SIZE ||
      Crc (P + 0x25B0, 0x808) != 0xA8F010FD ||
      Crc (P + 0x1C29C, 0xF4) != 0x44A408F0 ||
      Crc (P + 0x22994, 0xF0) != 0xE7DEB92E) return EFI_NOT_FOUND;
  // Loaded, relocated protocol table; a raw EFI file copy does not qualify.
  if (Le64 (P + 0x4E370) != LoadedBase + 0x24EC ||
      Le64 (P + 0x4E378) != LoadedBase + 0x25B0 ||
      Le64 (P + 0x4E380) != LoadedBase + 0x35C4 ||
      Le64 (P + 0x4E388) != LoadedBase + 0x5CB90 ||
      P[0x5CB88] != 1) return EFI_UNSUPPORTED;
  MaxMode = Le32 (P + 0x5CB90);
  Mode = Le32 (P + 0x5CB94);
  if (MaxMode == 0 || MaxMode > 8 || Mode >= MaxMode ||
      Le32 (P + 0x5D4E0) != MaxMode || Le32 (P + 0x5D4E4) != 0 ||
      Le32 (P + 0x5D4E8) != 0 || Le32 (P + 0x5CBB8) != Mode ||
      Le64 (P + 0x5CB98) != LoadedBase + 0x5CBBC || Le64 (P + 0x5CBA0) != 36 ||
      Le32 (P + 0x5CBBC) != 0x1000 || Le32 (P + 0x5CBC8) != 1 ||
      Le32 (P + 0x5D560) != 4 || Le32 (P + 0x5D564) != 1 || Le32 (P + 0x5D568) != 6 ||
      (Le32 (P + 0x63B08) & 0x4000)) return EFI_UNSUPPORTED;
  W = Le32 (P + 0x5CBC0); H = Le32 (P + 0x5CBC4);
  if (W == 0 || H == 0 || W > 8192 || H > 8192 || Le32 (P + 0x5CBDC) != W)
    return EFI_UNSUPPORTED;
  Pitch = W * 4;
  Extent = (UINT64)Pitch * H;
  Base = Le64 (P + 0x5CBA8); Bytes = Le64 (P + 0x5CBB0);
  if ((Base & 3) || Base < 0xFC800000ULL || Bytes != Extent || Bytes > 0x2B00000 ||
      Base - 0xFC800000ULL > 0x2B00000 - Bytes) return EFI_UNSUPPORTED;
  // Independent MDP surface description must agree with the exported GOP.
  if (Le32 (P + 0x5D570) != W || Le32 (P + 0x5D574) != H ||
      Le64 (P + 0x5D580) != Base || Le64 (P + 0x5D588) != Bytes ||
      Le32 (P + 0x5D590) != Pitch || Le32 (P + 0x6349C) != W ||
      Le32 (P + 0x634A0) != H || Le32 (P + 0x634B8) != Pitch ||
      Le32 (P + 0x6378C) != 1 || Le32 (P + 0x63790) == 0) return EFI_UNSUPPORTED;
  Out->Magic = MYRON_DISPLAY_MAGIC; Out->Version = 1; Out->Status = 1;
  Out->ImageBase = LoadedBase; Out->Base = Base; Out->Bytes = Bytes;
  Out->Width = W; Out->Height = H; Out->Stride = Pitch; Out->Format = 1;
  return EFI_SUCCESS;
}

EFI_STATUS MyronFindStockDisplay (CONST VOID *Memory, UINTN Size, UINT64 PhysicalBase,
                                 MYRON_DISPLAY_HANDOFF *Out)
{
  MYRON_DISPLAY_HANDOFF Found, Candidate;
  UINT32 Valid = 0, Recognized = 0;
  EFI_STATUS Status;
  CONST UINT8 *P = Memory;
  if (Out == NULL) return EFI_INVALID_PARAMETER;
  ZeroMem (Out, sizeof (*Out));
  if (P == NULL || Size < MYRON_STOCK_DISPLAY_SIZE || PhysicalBase < 0xB00F0000ULL ||
      (PhysicalBase & 0xFFF) || Size > 0x131A0000 || PhysicalBase > 0xC3290000ULL - Size)
    return EFI_INVALID_PARAMETER;
  ZeroMem (&Found, sizeof (Found));
  for (UINTN Offset = 0; Offset <= Size - MYRON_STOCK_DISPLAY_SIZE; Offset += 0x1000) {
    if (P[Offset] != 'M' || P[Offset + 1] != 'Z') continue;
    Status = MyronValidateStockDisplay (P + Offset, MYRON_STOCK_DISPLAY_SIZE, PhysicalBase + Offset, &Candidate);
    if (Status == EFI_NOT_FOUND) continue;
    Recognized++;
    if (!EFI_ERROR (Status)) { Found = Candidate; Valid++; }
  }
  if (Valid == 1) *Out = Found;
  else Out->Status = Valid > 1 ? 3 : (Recognized ? 2 : 0);
  Out->Magic = MYRON_DISPLAY_MAGIC; Out->Version = 1; Out->Recognized = Recognized;
  return Valid == 1 ? EFI_SUCCESS : EFI_NOT_FOUND;
}
