STATIC BOOLEAN MappedRam (UINT64 Address, UINT64 Length)
{
  EFI_MEMORY_REGION_DESCRIPTOR *Map;
  UINT8 Count;
  if (Address < 0x80000000 || Length == 0 || Address > MAX_UINT64 - Length) return FALSE;
  GetMemoryMap (&Map, &Count);
  for (UINTN I = 0; I < Count; I++) {
    if (Map[I].HobOption == NoHob || Map[I].HobOption == HobOnlyNoCacheSetting ||
        (Map[I].ResourceType != SYS_MEM && Map[I].ResourceType != MEM_RES)) continue;
    if (Address >= Map[I].Address && Length <= Map[I].Length &&
        Address - Map[I].Address <= Map[I].Length - Length) return TRUE;
  }
  return FALSE;
}

STATIC UINT64 Cells (CONST VOID *Data, INT32 Length)
{
  CONST UINT8 *P = Data;
  UINT64 Value = 0;
  for (INT32 I = 0; I < Length; I++) Value = (Value << 8) | P[I];
  return Value;
}

STATIC BOOLEAN ReservedInitrdRange (UINT64 Start, UINT64 End, UINT64 Fdt, UINT64 FdtSize)
{
  EFI_MEMORY_REGION_DESCRIPTOR *Map;
  UINT8 Count;
  if (End <= Start ||
      (Start < Fdt + FdtSize && Fdt < End)) return FALSE;
  GetMemoryMap (&Map, &Count);
  for (UINTN I = 0; I < Count; I++) {
    /* The working map keeps this whole arena reserved. Never publish data
     * from display/SMMU, the FD, SEC, the inherited heap, or our DXE heap. */
    if (AsciiStrCmp (Map[I].Name, "Kernel") == 0 &&
        Map[I].HobOption == AddMem && Map[I].ResourceType == SYS_MEM &&
        Map[I].MemoryType == EfiReservedMemoryType &&
        Start >= Map[I].Address && End - Start <= Map[I].Length &&
        Start - Map[I].Address <= Map[I].Length - (End - Start)) return TRUE;
  }
  return FALSE;
}

STATIC BOOLEAN PayloadRange (UINT64 Start, UINT64 End, UINT64 Fdt, UINT64 FdtSize)
{
  return ((Start | End) & 4095) == 0 && ReservedInitrdRange (Start, End, Fdt, FdtSize);
}

/* Helper uses the same reserved arena and original FDT checks. */
#include "KernelPayloadTransport.h"

STATIC BOOLEAN PublishablePayload (VOID *Fdt, UINT64 Address, UINT32 Size)
{
  INT32 Chosen, StartLength, EndLength;
  CONST VOID *StartProp, *EndProp;
  UINT64 Start, End;
  Chosen = FdtPathOffset (Fdt, "/chosen");
  if (Chosen < 0) return FALSE;
  StartProp = FdtGetProp (Fdt, Chosen, "linux,initrd-start", &StartLength);
  EndProp = FdtGetProp (Fdt, Chosen, "linux,initrd-end", &EndLength);
  if (StartProp == NULL || EndProp == NULL ||
      (StartLength != 4 && StartLength != 8) || (EndLength != 4 && EndLength != 8)) {
    DEBUG ((DEBUG_ERROR, "MYRON40: initrd absent or malformed cells start=%d end=%d\n", StartLength, EndLength));
    return FALSE;
  }
  Start = Cells (StartProp, StartLength); End = Cells (EndProp, EndLength);
  DEBUG ((DEBUG_ERROR, "MYRON40: original-initrd start=%lx end=%lx cells=%d/%d\n", Start, End, StartLength, EndLength));
  if (!ReservedInitrdRange (Start, End, Address, Size)) {
    DEBUG ((DEBUG_ERROR, "MYRON43: initrd refused: outside reserved Kernel arena or overlaps FDT\n"));
    return FALSE;
  }
  UINT64 Offset, Stop;
  if (!MyronLocatePayload ((CONST UINT8 *)(UINTN)Start, End - Start, &Offset, &Stop) ||
      !PayloadRange (Start + Offset, Start + Stop, Address, Size)) {
    DEBUG ((DEBUG_ERROR, "MYRON43: initrd refused: exact packaged payload not proven\n"));
    return FALSE;
  }
  UINT64 FatStart = Start + Offset, FatEnd = Start + Stop;
  UINT8 Encoded[8];
  for (INT32 I = 0; I < StartLength; I++) Encoded[StartLength - 1 - I] = (UINT8)(FatStart >> (I * 8));
  if (FdtSetProp (Fdt, Chosen, "linux,initrd-start", Encoded, StartLength) != 0) return FALSE;
  for (INT32 I = 0; I < EndLength; I++) Encoded[EndLength - 1 - I] = (UINT8)(FatEnd >> (I * 8));
  if (FdtSetProp (Fdt, Chosen, "linux,initrd-end", Encoded, EndLength) != 0) return FALSE;
  DEBUG ((DEBUG_ERROR, "MYRON43: payload published start=%lx end=%lx prefix=%lx suffix=%lx; source FDT untouched\n",
          FatStart, FatEnd, Offset, End - FatEnd));
  DEBUG ((DEBUG_ERROR, "MYRON40: initrd accepted: reserved MYRON FAT32 BPB; filesystem checks remain\n"));
  return TRUE;
}

VOID MyronPublishBootFdt (VOID)
{
  UINT64 Address = mMyronBootEntry.X0;
  UINT32 Size;
  VOID *Copy;
  INT32 Chosen;
  INT32 Result;
  BOOLEAN Payload;
  if ((Address & 7) != 0 || !MappedRam (Address, 40)) {
    DEBUG ((DEBUG_ERROR, "MYRON17: x0 FDT outside mapped RAM; menu continues without initrd\n"));
    return;
  }
  if (FdtCheckHeader ((VOID *)(UINTN)Address) != 0) {
    DEBUG ((DEBUG_ERROR, "MYRON17: x0 FDT header invalid; menu continues without initrd\n"));
    return;
  }
  Size = FdtTotalSize ((VOID *)(UINTN)Address);
  if (Size < 40 || Size > 0x200000 || !MappedRam (Address, Size)) {
    DEBUG ((DEBUG_ERROR, "MYRON17: x0 FDT extent rejected\n"));
    return;
  }
  Copy = AllocateReservedPages (EFI_SIZE_TO_PAGES (Size + 4096));
  if (Copy == NULL) return;
  if (FdtOpenInto ((VOID *)(UINTN)Address, Copy, Size + 4096) != 0) return;
  Chosen = FdtPathOffset (Copy, "/chosen");
  if (Chosen >= 0) FdtDelProp (Copy, Chosen, "myron,r48-payload-crc32");
  /* R48 needs the original initrd bounds, before the R43 fallback modifies them. */
  Payload = PublishKernelPayload (Copy, Address, Size);
  if (!Payload) {
    /* Recreate pristine input if a failed property write partially changed it. */
    if (FdtOpenInto ((VOID *)(UINTN)Address, Copy, Size + 4096) != 0) return;
    Chosen = FdtPathOffset (Copy, "/chosen");
    if (Chosen >= 0) FdtDelProp (Copy, Chosen, "myron,r48-payload-crc32");
    Payload = PublishablePayload (Copy, Address, Size);
  }
  DEBUG ((DEBUG_ERROR, "MYRON40: source-fdt address=%lx size=%x copy=%lx\n", Address, Size, (UINT64)(UINTN)Copy));
  /* Keep Android/vendor CPIO and unowned ranges away from shared Block I/O.
   * Validated plain FAT32 stays in the already-reserved source arena. */
  Chosen = FdtPathOffset (Copy, "/chosen");
  if (Chosen >= 0 && !Payload) {
    Result = FdtDelProp (Copy, Chosen, "linux,initrd-start");
    if (Result != 0 && Result != -FDT_ERR_NOTFOUND) return;
    Result = FdtDelProp (Copy, Chosen, "linux,initrd-end");
    if (Result != 0 && Result != -FDT_ERR_NOTFOUND) return;
  } else if (Chosen < 0 && Chosen != -FDT_ERR_NOTFOUND) {
    return;
  }
  Address = (UINT64)(UINTN)Copy;
  if (BuildGuidDataHob (&mEntryArgHobGuid, &Address, sizeof (Address)) == NULL) return;
  DEBUG ((DEBUG_ERROR, "MYRON40: reserved FDT HOB=%lx bytes=%u payload=%u\n", Address, Size, Payload));
}
