/* Read-only source retained in the bootloader's mapped, reserved Kernel arena.
 * There is no memory reclaim, destination write or arbitrary RAM scan here. */
STATIC BOOLEAN PublishKernelPayload (VOID *Copy, UINT64 Fdt, UINT32 FdtSize)
{
  CONST MYRON_KERNEL_PAYLOAD_ENTRY *P = &mMyronKernelPayloadEntry;
  INT32 Node, StartLength, EndLength;
  CONST VOID *StartProp, *EndProp;
  UINT64 Start, End, ImageEnd;
  UINT8 Encoded[8];
  UINT32 Crc;
  DEBUG ((DEBUG_ERROR, "MYRON48: TRANSPORT BEGIN magic=%lx image=%lx base=%lx bytes=%lx\n", P->Magic, P->ImageBase, P->Base, P->Bytes));
  if (P->Magic != MYRON_KERNEL_PAYLOAD_MAGIC || P->Bytes != MYRON_KERNEL_FAT_BYTES ||
      (P->ImageBase & 0x1fffff) || P->ImageBase > MAX_UINT64 - 0x301000ULL ||
      P->Base != P->ImageBase + 0x301000ULL || P->Base > MAX_UINT64 - P->Bytes) {
    DEBUG ((DEBUG_ERROR, "MYRON48: REFUSED shim descriptor\n")); return FALSE;
  }
  ImageEnd = P->Base + P->Bytes;
  if (!ReservedInitrdRange (P->ImageBase, ImageEnd, Fdt, FdtSize)) {
    DEBUG ((DEBUG_ERROR, "MYRON48: REFUSED image outside reserved Kernel arena or FDT overlap\n")); return FALSE;
  }
  Node = FdtPathOffset (Copy, "/chosen");
  if (Node < 0) { DEBUG ((DEBUG_ERROR, "MYRON48: REFUSED missing chosen\n")); return FALSE; }
  StartProp = FdtGetProp (Copy, Node, "linux,initrd-start", &StartLength);
  EndProp = FdtGetProp (Copy, Node, "linux,initrd-end", &EndLength);
  if (StartProp == NULL || EndProp == NULL || (StartLength != 4 && StartLength != 8) ||
      (EndLength != 4 && EndLength != 8)) {
    DEBUG ((DEBUG_ERROR, "MYRON48: REFUSED original initrd unavailable\n")); return FALSE;
  }
  Start = Cells (StartProp, StartLength); End = Cells (EndProp, EndLength);
  if (!ReservedInitrdRange (Start, End, Fdt, FdtSize) ||
      (P->ImageBase < End && Start < ImageEnd)) {
    DEBUG ((DEBUG_ERROR, "MYRON48: REFUSED original initrd range or image overlap\n")); return FALSE;
  }
  /* Only now is it permissible to read any appended source byte. */
  if (!MyronFatPayload ((CONST UINT8 *)(UINTN)P->Base, P->Bytes)) {
    DEBUG ((DEBUG_ERROR, "MYRON48: REFUSED FAT header\n")); return FALSE;
  }
  Crc = CalculateCrc32 ((VOID *)(UINTN)P->Base, (UINTN)P->Bytes);
  DEBUG ((DEBUG_ERROR, "MYRON48: full-payload CRC32=%x expected=%x bytes=%lx\n", Crc, MYRON_KERNEL_FAT_CRC32, P->Bytes));
  if (Crc != MYRON_KERNEL_FAT_CRC32) { DEBUG ((DEBUG_ERROR, "MYRON48: REFUSED payload CRC\n")); return FALSE; }
  for (UINTN I = 0; I < 8; I++) Encoded[7-I] = (UINT8)(P->Base >> (I*8));
  if (FdtSetProp (Copy, Node, "linux,initrd-start", Encoded, 8) != 0) return FALSE;
  for (UINTN I = 0; I < 8; I++) Encoded[7-I] = (UINT8)(ImageEnd >> (I*8));
  if (FdtSetProp (Copy, Node, "linux,initrd-end", Encoded, 8) != 0) return FALSE;
  for (UINTN I = 0; I < 4; I++) Encoded[3-I] = (UINT8)(Crc >> (I*8));
  if (FdtSetProp (Copy, Node, "myron,r48-payload-crc32", Encoded, 4) != 0) return FALSE;
  DEBUG ((DEBUG_ERROR, "MYRON48: PUBLISHED base=%lx bytes=%lx source-reserved=1; no copy or XNU execution\n", P->Base, P->Bytes));
  DEBUG ((DEBUG_ERROR, "MYRON48: payload-sha256=%a kernel-sha256=%a (host pins; runtime CRC32)\n", MYRON_KERNEL_FAT_SHA256, MYRON_R46_KERNEL_SHA256));
  return TRUE;
}
#endif
