#ifndef MYRON_PAYLOAD_POLICY_H
#define MYRON_PAYLOAD_POLICY_H

STATIC UINT32 MyronLe16 (CONST UINT8 *P)
{ return (UINT32)P[0] | ((UINT32)P[1] << 8); }
STATIC UINT32 MyronLe32 (CONST UINT8 *P)
{ return MyronLe16 (P) | (MyronLe16 (P + 2) << 16); }

/* Accept only the plain FAT32 layout emitted by UniXNU's mformat -F recipe.
 * Caller proves that all 512 bytes are mapped and the entire volume remains
 * reserved. This validates the BPB, not every directory/FAT entry. */
STATIC BOOLEAN MyronFatPayload (CONST UINT8 *B, UINT64 Bytes)
{
  UINT32 Total, Fat, Reserved, Spc, Fats, Root, Clusters;
  UINT64 Metadata;
  if (Bytes < 512 || (Bytes & 511) != 0 || Bytes / 512 > MAX_UINT32) return FALSE;
  if (!((B[0] == 0xeb && B[2] == 0x90) || B[0] == 0xe9) ||
      B[510] != 0x55 || B[511] != 0xaa || MyronLe16 (B + 11) != 512 ||
      MyronLe16 (B + 17) != 0 || MyronLe16 (B + 19) != 0 ||
      MyronLe16 (B + 22) != 0 || MyronLe32 (B + 28) != 0 ||
      MyronLe16 (B + 42) != 0 || B[66] != 0x29 ||
      CompareMem (B + 71, "MYRON      ", 11) != 0 ||
      CompareMem (B + 82, "FAT32   ", 8) != 0) return FALSE;
  Total = MyronLe32 (B + 32); Fat = MyronLe32 (B + 36);
  Reserved = MyronLe16 (B + 14); Spc = B[13]; Fats = B[16];
  Root = MyronLe32 (B + 44);
  if (Total != Bytes / 512 || Reserved == 0 || Fat == 0 ||
      Spc == 0 || Spc > 128 || (Spc & (Spc - 1)) != 0 ||
      (Fats != 1 && Fats != 2)) return FALSE;
  Metadata = Reserved + (UINT64)Fats * Fat;
  if (Metadata >= Total) return FALSE;
  Clusters = (UINT32)((Total - Metadata) / Spc);
  if (Clusters < 65525 || Clusters >= 0x0ffffff5 ||
      (UINT64)Fat * 128 < (UINT64)Clusters + 2 || Root < 2 ||
      Root - 2 >= Clusters) return FALSE;
  return TRUE;
}
