#ifndef MYRON_PAYLOAD_TRANSPORT_H
#define MYRON_PAYLOAD_TRANSPORT_H
#include "PayloadExpected.h"

/* Android v4 may concatenate vendor ramdisks, generic ramdisk and bootconfig.
 * Peel only a valid terminal bootconfig trailer, then take the exact packaged
 * generic-ramdisk length. Never scan arbitrary RAM or accept a BPB alone.
 * Caller proves the WHOLE input is in reserved mapped RAM and disjoint from FDT.
 * CRC32 detects accidental corruption/wrong payload; it is NOT authentication.
 * The host package is pinned with SHA256. This bring-up payload has no kernel.
 */
STATIC BOOLEAN MyronLocatePayload (CONST UINT8 *Raw, UINT64 Bytes,
                                   UINT64 *Offset, UINT64 *PayloadEnd)
{
  UINT64 End = Bytes;
  if (Bytes < 20 || Bytes > 0x10000000ULL) return FALSE;
  BOOLEAN Bootconfig = CompareMem (Raw + Bytes - 12, "#BOOTCONFIG\n", 12) == 0;
  DEBUG ((DEBUG_ERROR, "MYRON43: transport bytes=%lx bootconfig-magic=%u\n", Bytes, Bootconfig));
  if (Bootconfig) {
    UINT32 Size = MyronLe32 (Raw + Bytes - 20);
    UINT32 Expected = MyronLe32 (Raw + Bytes - 16), Sum = 0;
    if (Size == 0 || Size > 0x10000 || Size > Bytes - 20) {
      DEBUG ((DEBUG_ERROR, "MYRON43: payload refused: bootconfig size=%x\n", Size));
      return FALSE;
    }
    End = Bytes - 20 - Size;
    for (UINT32 I = 0; I < Size; I++) Sum += Raw[End + I];
    DEBUG ((DEBUG_ERROR, "MYRON43: bootconfig size=%x checksum=%x expected=%x\n", Size, Sum, Expected));
    if (Sum != Expected) return FALSE;
  }
  if (End < MYRON_PAYLOAD_BYTES) return FALSE;
  UINT64 Start = End - MYRON_PAYLOAD_BYTES;
  if ((((UINT64)(UINTN)Raw + Start) & 4095) != 0 ||
      !MyronFatPayload (Raw + Start, MYRON_PAYLOAD_BYTES)) {
    DEBUG ((DEBUG_ERROR, "MYRON43: payload refused: tail FAT32/alignment offset=%lx end=%lx\n", Start, End));
    return FALSE;
  }
  UINT32 Crc = CalculateCrc32 ((VOID *)(UINTN)(Raw + Start), MYRON_PAYLOAD_BYTES);
  DEBUG ((DEBUG_ERROR, "MYRON43: payload CRC32=%x expected=%x bytes=%x\n", Crc, MYRON_PAYLOAD_CRC32, MYRON_PAYLOAD_BYTES));
  if (Crc != MYRON_PAYLOAD_CRC32) return FALSE;
  DEBUG ((DEBUG_ERROR, "MYRON43: expected-payload-sha256=%a (host pin; runtime CRC32)\n", MYRON_PAYLOAD_SHA256));
  *Offset = Start; *PayloadEnd = End;
  return TRUE;
}
#endif
