#ifndef MYRON_PROBE_STAGE
#define MYRON_PROBE_STAGE 0
#endif
#if MYRON_PROBE_STAGE != 0
VOID MyronProbeReset (VOID);
VOID MyronStageProbeReset (UINTN Seconds);
#endif



STATIC
EFI_STATUS
InitializeMemory (VOID)
{
  EFI_STATUS                    Status;
  EFI_MEMORY_REGION_DESCRIPTOR  UefiMemoryRegion;
  EFI_HOB_HANDOFF_INFO_TABLE   *HobList;

  // Locate "DXE Heap" Memory Region
  LocateMemoryRegionByName ("DXE Heap", &UefiMemoryRegion);
  LocateMemoryRegionByName ("DXE_Heap", &UefiMemoryRegion);

  // Save UEFI Memory Details
  UINTN UefiMemoryBase = UefiMemoryRegion.Address;
  UINTN UefiMemorySize = UefiMemoryRegion.Length;

  // Verify UEFI Memory Base
  if (UefiMemoryBase == 0 && UefiMemorySize == 0) {
    DEBUG ((EFI_D_ERROR, "Failed to Locate \"DXE Heap\" Memory Region!\n"));
    return EFI_NOT_FOUND;
  }

  // Initialize HOB List
  HobList = HobConstructor ((VOID *)UefiMemoryBase, UefiMemorySize, (VOID *)UefiMemoryBase, (VOID *)(UefiMemoryBase + UefiMemorySize));
  PrePeiSetHobList (HobList);

  // Initialize MMU & Memory HOBs
  Status = MemoryPeim (UefiMemoryBase, UefiMemorySize);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  // Build Stack HOB
  BuildStackHob (FixedPcdGet64 (PcdCPUCoresStackBase), FixedPcdGet32 (PcdCPUCorePrimaryStackSize));

  return EFI_SUCCESS;
}

STATIC
VOID
SecMain (VOID)
{
  EFI_STATUS Status;

  // Do Platform Specific Initialization
  PlatformInitialize ();



  // Initialize Memory
  DEBUG ((DEBUG_ERROR, "MYRON17: memory/MMU begin\n"));
  Status = InitializeMemory ();
  DEBUG ((DEBUG_ERROR, "MYRON17: memory/MMU %r\n", Status));
  if (EFI_ERROR (Status)) {
    return;
  }

  #if MYRON_PROBE_STAGE == 2
  // Stop before stock SEC callbacks or DXE: memory initialization succeeded.
  MyronProbeReset ();
  #endif

  // Build CPU HOB
  BuildCpuHob (ArmGetPhysicalAddressBits (), PcdGet8 (PcdPrePiCpuIoSize));

  // Set the Boot Mode
  SetBootMode (BOOT_WITH_DEFAULT_SETTINGS);

  // Initialize Platform HOBs
  DEBUG ((DEBUG_ERROR, "MYRON17: PEI begin\n"));
  Status = PlatformPeim ();
  DEBUG ((DEBUG_ERROR, "MYRON17: PEI %r\n", Status));
  #if MYRON_PROBE_STAGE == 5 || MYRON_PROBE_STAGE == 6 || MYRON_PROBE_STAGE == 7 || MYRON_PROBE_STAGE == 8 || MYRON_PROBE_STAGE == 9 || MYRON_PROBE_STAGE == 10 || MYRON_PROBE_STAGE == 11 || MYRON_PROBE_STAGE == 12 || MYRON_PROBE_STAGE == 13 || MYRON_PROBE_STAGE == 14 || MYRON_PROBE_STAGE == 15 || MYRON_PROBE_STAGE == 16 || MYRON_PROBE_STAGE == 17 || MYRON_PROBE_STAGE == 18 || MYRON_PROBE_STAGE == 19
  if (EFI_ERROR (Status)) MyronStageProbeReset (3);
  #endif
  #if MYRON_PROBE_STAGE == 3 || MYRON_PROBE_STAGE == 4
  // r20 changes only success delay (9 -> 29); error remains 3. No DXE.
  MyronStageProbeReset (EFI_ERROR (Status) ? 3 : (MYRON_PROBE_STAGE == 4 ? 29 : 9));
  #endif
  if (EFI_ERROR (Status)) {
    return;
  }

  // Run Library Cconstructors
  DEBUG ((DEBUG_ERROR, "MYRON17: SEC constructors begin\n"));
  ProcessLibraryConstructorList ();
  DEBUG ((DEBUG_ERROR, "MYRON17: SEC constructors done\n"));

  // Decompress all FVs
  DEBUG ((DEBUG_ERROR, "MYRON17: FV decompression begin\n"));
  Status = DecompressFirstFv ();
  DEBUG ((DEBUG_ERROR, "MYRON17: FV decompression %r\n", Status));
  if (EFI_ERROR (Status)) {
    DEBUG ((EFI_D_ERROR, "Failed to Decompress FV! Status = %r\n", Status));
    #if MYRON_PROBE_STAGE == 5 || MYRON_PROBE_STAGE == 6 || MYRON_PROBE_STAGE == 7 || MYRON_PROBE_STAGE == 8 || MYRON_PROBE_STAGE == 9 || MYRON_PROBE_STAGE == 10 || MYRON_PROBE_STAGE == 11 || MYRON_PROBE_STAGE == 12 || MYRON_PROBE_STAGE == 13 || MYRON_PROBE_STAGE == 14 || MYRON_PROBE_STAGE == 15 || MYRON_PROBE_STAGE == 16 || MYRON_PROBE_STAGE == 17 || MYRON_PROBE_STAGE == 18 || MYRON_PROBE_STAGE == 19
    MyronStageProbeReset (6);
    #endif
    return;
  }

  // Load DXE Core
  DEBUG ((DEBUG_ERROR, "MYRON17: enter DXE core\n"));
  Status = LoadDxeCoreFromFv (NULL, 0);
  DEBUG ((DEBUG_ERROR, "MYRON17: DXE returned %r\n", Status));
  #if MYRON_PROBE_STAGE == 5 || MYRON_PROBE_STAGE == 6 || MYRON_PROBE_STAGE == 7 || MYRON_PROBE_STAGE == 8 || MYRON_PROBE_STAGE == 9 || MYRON_PROBE_STAGE == 10 || MYRON_PROBE_STAGE == 11 || MYRON_PROBE_STAGE == 12 || MYRON_PROBE_STAGE == 13 || MYRON_PROBE_STAGE == 14 || MYRON_PROBE_STAGE == 15 || MYRON_PROBE_STAGE == 16 || MYRON_PROBE_STAGE == 17 || MYRON_PROBE_STAGE == 18 || MYRON_PROBE_STAGE == 19
  // The DXE entry checkpoint must never return to SEC.
  MyronStageProbeReset (9);
  #endif
  if (EFI_ERROR (Status)) {
    DEBUG ((EFI_D_ERROR, "Failed to Load DXE Core! Status = %r\n", Status));
  }
}

VOID
SecEntry (VOID)
{
  #if MYRON_PROBE_STAGE == 1
  // SEC stack/C entry reached; no SMMU, MMU, logger or display initialization.
  MyronProbeReset ();
  #endif
  // Disable Data Cache
  ArmDisableDataCache ();

  // Invalidate Instruction Cache
  ArmInvalidateInstructionCache ();

  // Enable Instruction Cache
  ArmEnableInstructionCache ();

  // Invalidate Stack & UEFI FD D-Cache
  InvalidateDataCacheRange ((VOID *)FixedPcdGet64 (PcdCPUCoresStackBase), FixedPcdGet32 (PcdCPUCorePrimaryStackSize));
  InvalidateDataCacheRange ((VOID *)FixedPcdGet64 (PcdFdBaseAddress),     FixedPcdGet32 (PcdFdSize));

  // Verify Exception Vector Table
  ASSERT (((UINTN)SecVectorTable & ARM_VECTOR_TABLE_ALIGNMENT) == 0);

  // Enable new Exception Vector Table
  ArmWriteVBar ((UINTN)SecVectorTable);

  // Enter Main SEC Function
  SecMain ();
}
