// SPDX-License-Identifier: MIT
// Board adapter for UniXNU's boot_progress hooks and sheng's bounded render core.
// No MMIO, mapping changes, worker threads, storage operations or reset policy.
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <pexpert/pexpert.h>
#include <kern/boot_progress.h>
#include "BootProgressCore.h"
#include "BootProgressDisplay.h"
struct bp_core myron_boot_progress_state;
// Writable diagnostic storage survives the VM permission transition.
uint64_t myron_probe_context[16];
volatile uint64_t myron_console_bind_count;
struct bp_display myron_boot_display;
#define display myron_boot_display
static unsigned enabled, busy;
struct myron_mount_slot {
 char phase[BP_COLS], name[BP_COLS];
 uint64_t a, b, events;
 unsigned at;
};
// Last software event per path, not an atomic hardware snapshot or a verdict.
struct myron_mount_slot myron_mount_slots[5];
volatile uint64_t myron_mount_dropped;
static unsigned mount_started, mount_refresh;
// Independent diagnostic rows: do not take the normal console/cache writer lock.
static unsigned irq_busy, irq_refresh, panic_claimed;
volatile uint64_t myron_irq_pc, myron_irq_psr, myron_irq_sp, myron_irq_returns;
volatile uint64_t myron_panic_pc, myron_panic_lr, myron_panic_esr, myron_panic_far;


// 0: console owns framebuffer; 1: drain writer; 2: scanout; 3: release native console.
// Keep boot_progress_active() true after handoff so video/serial hooks continue
// consuming text here rather than falling back to another framebuffer writer.
static unsigned scanout_state;
volatile uint64_t myron_scanout_prepare_calls, myron_scanout_cancel_calls;
volatile int myron_scanout_release_status;
static uint64_t frequency, epoch;
volatile uint64_t myron_boot_progress_irqs;
volatile uint64_t myron_last_user_abort_esr, myron_last_user_abort_far;
volatile uint64_t myron_user_abort_count;
static void append_text(char *out, unsigned *at, const char *s) {
 while (*at < BP_COLS-1 && *s) out[(*at)++] = *s++;
 out[*at] = 0;
}
static void append_hex(char *out, unsigned *at, uint64_t value) {
 static const char hex[] = "0123456789abcdef";
 append_text(out,at,"0x");
 for (int shift=60;shift>=0;shift-=4) {
  char c[2]={hex[(value>>shift)&15],0};append_text(out,at,c);
 }
}
static unsigned seconds(void) {
 uint64_t t; __asm__ volatile("mrs %0, cntvct_el0":"=r"(t));
 return frequency ? (unsigned)((t-epoch)/frequency) : 0;
}
// Before platform panic hooks: no formatting varargs, locks, allocation, MMIO
// reads, storage or scheduler calls. A nested fault cannot recurse into drawing.
void myron_boot_progress_fault(const char *message,uint64_t pc,uint64_t lr,uint64_t esr,uint64_t far) {
 if(!enabled || !display.bound || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE))return;
 if(__atomic_exchange_n(&panic_claimed,1,__ATOMIC_ACQ_REL))return;
 myron_panic_pc=pc;myron_panic_lr=lr;myron_panic_esr=esr;myron_panic_far=far;
 if(__atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE))return;
 char line[BP_COLS]={0};unsigned at=0;
 // Publish numeric evidence first in case a corrupt panic message itself faults.
 append_text(line,&at,"PC=");append_hex(line,&at,pc);
 append_text(line,&at," LR=");append_hex(line,&at,lr);
 bp_line(&display,46,line,0xffff4040);
 at=0;line[0]=0;append_text(line,&at,"ESR=");append_hex(line,&at,esr);
 append_text(line,&at," FAR=");append_hex(line,&at,far);
 bp_line(&display,47,line,0xffff4040);
 at=0;line[0]=0;append_text(line,&at,"EARLY PANIC: ");
 append_text(line,&at,message ? message : "(no format string)");
 bp_line(&display,45,line,0xffff4040);
}
void myron_boot_progress_panic(const char *format,uint64_t caller) {
 // For an ordinary panic PC is the caller, LR is zero; ESR/FAR are not inferred.
 myron_boot_progress_fault(format,caller,0,0,0);
}
void myron_boot_progress_irq_return(void) { ++myron_irq_returns; }
static void draw_irq(unsigned now) {
 if(!display.bound || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE) ||
    __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE))return;
 char line[BP_COLS]={0};unsigned at=0;
 append_text(line,&at,"IRQ PC=");append_hex(line,&at,myron_irq_pc);
 append_text(line,&at," SPSR=");append_hex(line,&at,myron_irq_psr);
 append_text(line,&at,__atomic_load_n(&busy,__ATOMIC_ACQUIRE) ? " console=BUSY" : " console=free");
 bp_line(&display,25,line,0xff80ff80);
 at=0;line[0]=0;append_text(line,&at,"IRQ enter=");append_hex(line,&at,myron_boot_progress_irqs);
 append_text(line,&at," return=");append_hex(line,&at,myron_irq_returns);
 append_text(line,&at," sec=");append_hex(line,&at,now);
 bp_line(&display,27,line,0xff80ff80);
}
static void draw_mount(void) {
 if (!mount_started || !display.bound || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE)) return;
 char line[BP_COLS]={0}; unsigned at=0;
 append_text(line,&at,"ROOT MOUNT cached events; seconds=");append_hex(line,&at,seconds());
 append_text(line,&at," IRQ=");append_hex(line,&at,myron_boot_progress_irqs);
 bp_line(&display,26,line,0xffffff00);
 for(unsigned i=0;i<5;i++) {
  const struct myron_mount_slot *v=&myron_mount_slots[i];
  static const char *names[]={"ROOT ","VFS  ","UFS  ","HOST ","REQ  "};
  at=0;line[0]=0;append_text(line,&at,names[i]);append_text(line,&at,v->phase);
  append_text(line,&at," ");append_text(line,&at,v->name);
  bp_line(&display,28+i*3,line,0xff00ffff);
  at=0;line[0]=0;append_text(line,&at,"a=");append_hex(line,&at,v->a);
  append_text(line,&at," b=");append_hex(line,&at,v->b);
  append_text(line,&at," count=");append_hex(line,&at,v->events);
  bp_line(&display,29+i*3,line,0xffffffff);
 }
 at=0;line[0]=0;append_text(line,&at,"Observer dropped=");append_hex(line,&at,myron_mount_dropped);
 bp_line(&display,44,line,0xffffff00);
}
void myron_mount_event(unsigned slot,const char *phase,const char *name,uint64_t a,uint64_t b) {
 if(!enabled || slot>=5)return;
 if(__atomic_exchange_n(&busy,1,__ATOMIC_ACQUIRE)) {
  __atomic_fetch_add(&myron_mount_dropped,1,__ATOMIC_RELAXED);return;
 }
 struct myron_mount_slot *v=&myron_mount_slots[slot];
 bp_copy(v->phase,phase);bp_copy(v->name,name);v->a=a;v->b=b;++v->events;v->at=seconds();
 mount_started=1;
 // I/O hot paths only store cached values. The IRQ refresh takes no driver
 // locks and performs no MMIO reads, allocation, mapping or scheduling.
 if(slot<2)draw_mount();
 __atomic_store_n(&busy,0,__ATOMIC_RELEASE);
}
static void draw(void) {
 if (!display.bound || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE)) return;
 struct bp_core *s=&myron_boot_progress_state;
 bp_line(&display,0,"MYRON iOS27 - CONTINUOUS XNU BOOT",0xff00ff00);
 bp_line(&display,1,"MYRON STALL TRACE 2 - early panic / independent IRQ",0xff80ff80);
 unsigned n=s->history_count<BP_HISTORY?s->history_count:BP_HISTORY;
 for(unsigned i=0;i<n;i++)bp_line(&display,2+i,s->history[(s->history_count-n+i)%BP_HISTORY].text,0xff00ffff);
 bp_line(&display,9,"Kernel console; photograph the last stage on a stall",0xffffff00);
 n=s->log_lines+1<BP_LOGS?s->log_lines+1:BP_LOGS;
 for(unsigned i=0;i<n;i++)bp_line(&display,11+i,s->logs[(s->log_row+BP_LOGS+1-n+i)%BP_LOGS],0xffffffff);
 draw_mount();
}
void boot_progress_init(void) {
 unsigned opt=0;
 if(!PE_parse_boot_argn("boot-progress",&opt,sizeof opt) || opt!=2)return;
 __asm__ volatile("mrs %0, cntfrq_el0":"=r"(frequency));
 __asm__ volatile("mrs %0, cntvct_el0":"=r"(epoch));
 enabled=1;myron_boot_progress_state.continuous=1;
 myron_boot_progress_state.limit=120;myron_boot_progress_state.stall=30;
 boot_progress_stage("PE initialized; native mappings pending");
}
int boot_progress_active(void) { return enabled; }
int myron_boot_progress_prepare_scanout(void) {
 if(!enabled || __atomic_load_n(&panic_claimed,__ATOMIC_ACQUIRE))return 0; // Do not release a panic display.
 ++myron_scanout_prepare_calls;
 unsigned expected=0;
 (void)__atomic_compare_exchange_n(&scanout_state,&expected,1,0,__ATOMIC_ACQ_REL,__ATOMIC_ACQUIRE);
 if(expected==2)return 1;
 if(expected==3)return 0;
 if(__atomic_exchange_n(&busy,1,__ATOMIC_ACQUIRE))return 0;
 if(__atomic_exchange_n(&irq_busy,1,__ATOMIC_ACQUIRE)) {
  __atomic_store_n(&busy,0,__ATOMIC_RELEASE);return 0;
 }
 __atomic_store_n(&scanout_state,3,__ATOMIC_RELEASE);
 // The native console has separate text/progress locks. Its release operation
 // disables those writers too; recursive boot-progress output simply drops
 // while busy is held. Never acknowledge before this operation returns.
 myron_scanout_release_status=PE_initialize_console(NULL,kPEReleaseScreen);
 if(myron_scanout_release_status) {
  __atomic_store_n(&scanout_state,1,__ATOMIC_RELEASE);
  __atomic_store_n(&irq_busy,0,__ATOMIC_RELEASE);
  __atomic_store_n(&busy,0,__ATOMIC_RELEASE);return 0;
 }
 // Owning busy proves the previous console writer has completed. All future
 // bind/draw paths observe state 2 before issuing any framebuffer store.
 __atomic_store_n(&scanout_state,2,__ATOMIC_RELEASE);
 __atomic_store_n(&irq_busy,0,__ATOMIC_RELEASE);
 __atomic_store_n(&busy,0,__ATOMIC_RELEASE);
 return 1;
}
void myron_boot_progress_cancel_scanout(void) {
 ++myron_scanout_cancel_calls;
 unsigned expected=1;
 // Cancel only a pending transition. Once acknowledged, never let a timeout
 // or late cancellation resume text writes over userspace frames.
 (void)__atomic_compare_exchange_n(&scanout_state,&expected,0,0,__ATOMIC_ACQ_REL,__ATOMIC_ACQUIRE);
}
void boot_progress_bind(uintptr_t base,unsigned w,unsigned h,unsigned stride,unsigned depth) {
 if(!enabled || __atomic_exchange_n(&busy,1,__ATOMIC_ACQUIRE))return;
 if(__atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE)) {
  __atomic_store_n(&busy,0,__ATOMIC_RELEASE);return;
 }
 display.bound=0;
 // Same ownership rule as sheng: caller already created an XNU mapping.
 if(base>=0xffff000000000000ULL && depth==32 && w>=720 && w<=4096 && h>=560 && h<=4096 &&
    stride>=w*4 && stride<=65536 && base<=UINTPTR_MAX-(uint64_t)h*stride) {
  display.frame=base;display.width=w;display.height=h;display.stride=stride;display.scale=2;
  memset(display.previous,0,sizeof display.previous);memset(display.colors,0,sizeof display.colors);
  display.bound=1;bp_clear(&display);draw();++myron_console_bind_count;
 }
 __atomic_store_n(&busy,0,__ATOMIC_RELEASE);
}
void boot_progress_stage(const char *text) {
 if(!enabled || __atomic_exchange_n(&busy,1,__ATOMIC_ACQUIRE))return;
 bp_stage(&myron_boot_progress_state,text,seconds());draw();
 __atomic_store_n(&busy,0,__ATOMIC_RELEASE);
}
void boot_progress_putc(char c) {
 if(!enabled || __atomic_exchange_n(&busy,1,__ATOMIC_ACQUIRE))return;
 bp_char(&myron_boot_progress_state,c);if(c=='\n')draw();
 __atomic_store_n(&busy,0,__ATOMIC_RELEASE);
}
void boot_progress_start(void) { boot_progress_stage("kernel bootstrap clock services created"); }
void boot_progress_poll(void) {
 if(!enabled || __atomic_exchange_n(&busy,1,__ATOMIC_ACQUIRE))return;
 (void)bp_poll(&myron_boot_progress_state,seconds(),0,0,0);
 __atomic_store_n(&busy,0,__ATOMIC_RELEASE);
}
void boot_progress_irq(uint64_t pc,uint64_t psr,uint64_t sp) {
 myron_irq_pc=pc;myron_irq_psr=psr;myron_irq_sp=sp;++myron_boot_progress_irqs;
 if(!enabled || !mount_started || __atomic_load_n(&scanout_state,__ATOMIC_ACQUIRE))return;
 unsigned now=seconds();
 if(now!=irq_refresh && !__atomic_exchange_n(&irq_busy,1,__ATOMIC_ACQUIRE)) {
  irq_refresh=now;draw_irq(now);__atomic_store_n(&irq_busy,0,__ATOMIC_RELEASE);
 }
 if(now==mount_refresh || __atomic_exchange_n(&busy,1,__ATOMIC_ACQUIRE))return;
 mount_refresh=now;draw_mount();
 __atomic_store_n(&busy,0,__ATOMIC_RELEASE);
}
void boot_progress_user_breakpoint(void *p,unsigned e) {(void)p;(void)e;boot_progress_stage("user breakpoint");}
void boot_progress_user_abort(void *p,unsigned e,uint64_t a) {
 (void)p;
 // Ordinary demand paging also enters here: record without repainting each fault.
 myron_last_user_abort_esr=e;myron_last_user_abort_far=a;++myron_user_abort_count;
}
void boot_progress_critical_exit(int p,char *s,unsigned long n) {(void)p;(void)n;boot_progress_stage(s);}
void boot_progress_process_stage(int p,const char *name,const char *s) {
 (void)p;char text[BP_COLS]={0};unsigned n=0;
 append_text(text,&n,name);append_text(text,&n,": ");append_text(text,&n,s);
 boot_progress_stage(text);
}
void boot_progress_exit(int p,const char *name,int status,unsigned ns,uint64_t code) {
 char text[BP_COLS]={0};unsigned n=0;
 append_text(text,&n,name);append_text(text,&n," exit pid=");append_hex(text,&n,(unsigned)p);
 append_text(text,&n," status=");append_hex(text,&n,(unsigned)status);boot_progress_stage(text);
 n=0;append_text(text,&n,"exit namespace=");append_hex(text,&n,ns);
 append_text(text,&n," code=");append_hex(text,&n,code);boot_progress_stage(text);
}

