    (a.out/'replay.json').write_text(json.dumps(report,indent=2)+'\n')
    if not a.keep_ram:ram.unlink()
    print(json.dumps(dict(panic=snapshots[-1]['panic'],counters=snapshots[-1]['counters'],frames=[f['symbol'] for f in snapshots[-1]['frames'][-8:]])))

