            source.write_text('int check(int i, unsigned long n) { return i < n; }\n')
            record = dict(directory=str(directory), file=str(source),
                arguments=['c++', '-xc', '-c', str(source), '-o', 'original.o',
                           '-Wall', '-Wextra', '-Wno-error', '-Wno-sign-compare',
                           '-MD', '-MF', 'original.d', '-MJ', 'original.json'])
            builder = module('warning_regression_builder', ARGS.upstream / 'scripts/build-sheng-source-drivers.py')
            old = builder.compile_command(record, source, output, [], [])
            failure = subprocess.run(old, capture_output=True, text=True)
            self.assertNotEqual(failure.returncode, 0)
            self.assertIn('sign-compare', failure.stderr)
            command = kernel_c_command(record, source, output)
            subprocess.run(command, check=True)
            self.assertTrue(output.is_file())
            self.assertFalse((directory / 'original.o').exists())
            self.assertFalse((directory / 'original.d').exists())
            self.assertFalse((directory / 'original.json').exists())
            self.assertEqual([v for v in command if v.startswith('-W')],
                             [v for v in record['arguments'] if v.startswith('-W')])
            # Preserving warnings must never turn a true C error into success.
            source.write_text('int check(void) { return undeclared_root_device; }\n')
            self.assertNotEqual(subprocess.run(command, capture_output=True).returncode, 0)
            for arguments in (record['arguments'] + [str(source)],
                              [v for v in record['arguments'] if v != '-c']):
                with self.assertRaises(ValueError):
                    kernel_c_command({**record, 'arguments': arguments}, source, output)

